/* DAWAH X — darimi, অধ্যায় 9 · খণ্ড 9 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['darimi'][9]=[[1601,1601,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَتَصَدَّقَ فَوَافَقَ ذَلِكَ مَالًا عِنْدِي فَقُلْتُ الْيَوْمَ أَسْبِقُ ‏ ‏أَبَا بَكْرٍ ‏ ‏إِنْ سَبَقْتُهُ يَوْمًا فَجِئْتُ بِنِصْفِ مَالِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أَبْقَيْتَ لِأَهْلِكَ قُلْتُ مِثْلَهُ قَالَ فَأَتَى ‏ ‏أَبُو بَكْرٍ ‏ ‏بِكُلِّ مَا عِنْدَهُ فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏مَا أَبْقَيْتَ لِأَهْلِكَ فَقَالَ أَبْقَيْتُ لَهُمْ اللَّهَ وَرَسُولَهُ فَقُلْتُ لَا أُسَابِقُكَ إِلَى شَيْءٍ أَبَدًا ‏","","",""],[1602,1602,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏فَرَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَكَاةَ الْفِطْرِ مِنْ رَمَضَانَ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ عَلَى كُلِّ حُرٍّ وَعَبْدٍ ذَكَرٍ أَوْ أُنْثَى مِنْ الْمُسْلِمِينَ ‏ ‏قِيلَ ‏ ‏لِأَبِي مُحَمَّدٍ ‏ ‏تَقُولُ بِهِ قَالَ ‏ ‏مَالِكٌ ‏ ‏كَانَ يَقُولُ بِهِ ‏","","",""],[1603,1603,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِزَكَاةِ الْفِطْرِ عَنْ كُلِّ صَغِيرٍ وَكَبِيرٍ حُرٍّ أَوْ عَبْدٍ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَعَدَلَهُ النَّاسُ ‏ ‏بِمُدَّيْنِ ‏ ‏مِنْ ‏ ‏بُرٍّ ‏","","",""],[1604,1604,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُخْرِجُ زَكَاةَ الْفِطْرِ إِذْ كَانَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ كُلِّ صَغِيرٍ وَكَبِيرٍ حُرٍّ وَمَمْلُوكٍ ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ ‏ ‏أَقِطٍ ‏ ‏أَوْ صَاعًا مِنْ زَبِيبٍ ‏ ‏فَلَمْ يَزَلْ ذَلِكَ كَذَلِكَ حَتَّى قَدِمَ عَلَيْنَا ‏ ‏مُعَاوِيَةُ ‏ ‏الْمَدِينَةَ ‏ ‏حَاجًّا أَوْ مُعْتَمِرًا فَقَالَ إِنِّي ‏ ‏أَرَى ‏ ‏مُدَّيْنِ ‏ ‏مِنْ ‏ ‏سَمْرَاءِ ‏ ‏الشَّامِ ‏ ‏يَعْدِلُ ‏ ‏صَاعًا ‏ ‏مِنْ التَّمْرِ فَأَخَذَ النَّاسُ بِذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَمَّا أَنَا فَلَا أَزَالُ أُخْرِجُهُ كَمَا كُنْتُ أُخْرِجُهُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَرَى ‏ ‏صَاعًا ‏ ‏مِنْ كُلِّ شَيْءٍ ‏","","",""],[1605,1605,"","","‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ بْنِ سَعْدِ بْنِ أَبِي سَرْحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا ‏ ‏نُخْرِجُ زَكَاةَ الْفِطْرِ مِنْ رَمَضَانَ ‏ ‏صَاعًا ‏ ‏مِنْ طَعَامٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ شَعِيرٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ زَبِيبٍ أَوْ ‏ ‏صَاعًا ‏ ‏مِنْ ‏ ‏أَقِطٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏كُنَّا نُعْطِي عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[1606,1606,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُقْبَةَ بْنَ عَامِرٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ صَاحِبُ ‏ ‏مَكْسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي عَشَّارًا ‏","","",""],[1607,1607,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏مُعَاذٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْيَمَنِ ‏ ‏فَأَمَرَنِي ‏ ‏أَنْ آخُذَ مِنْ الثِّمَارِ مَا سُقِيَ ‏ ‏بَعْلًا ‏ ‏الْعُشْرَ وَمَا سُقِيَ ‏ ‏بِالسَّانِيَةِ ‏ ‏فَنِصْفَ الْعُشْرِ ‏","","",""],[1608,1608,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَأَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جُرْحُ ‏ ‏الْعَجْمَاءِ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمُسُ ‏","","",""],[1609,1609,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْيَمَانِ الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي حُمَيْدٍ الْأَنْصَارِيِّ ثُمَّ السَّاعِدِيِّ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَعْمَلَ عَامِلًا عَلَى الصَّدَقَةِ فَجَاءَهُ الْعَامِلُ حِينَ فَرَغَ مِنْ عَمَلِهِ فَقَالَ يَا رَسُولَ اللَّهِ هَذَا الَّذِي لَكُمْ وَهَذَا أُهْدِيَ لِي فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَهَلَّا قَعَدْتَ فِي بَيْتِ أَبِيكَ وَأُمِّكَ فَنَظَرْتَ أَيُهْدَى لَكَ أَمْ لَا ثُمَّ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشِيَّةً بَعْدَ الصَّلَاةِ عَلَى الْمِنْبَرِ فَتَشَهَّدَ وَأَثْنَى عَلَى اللَّهِ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ أَمَّا بَعْدُ مَا بَالُ الْعَامِلِ نَسْتَعْمِلُهُ فَيَأْتِينَا فَيَقُولُ هَذَا مِنْ عَمَلِكُمْ وَهَذَا أُهْدِيَ لِي فَهَلَّا قَعَدَ فِي بَيْتِ أَبِيهِ وَأُمِّهِ فَيَنْظُرَ هَلْ يُهْدَى لَهُ أَمْ لَا وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَا ‏ ‏يَغُلُّ ‏ ‏أَحَدُكُمْ مِنْهَا شَيْئًا إِلَّا جَاءَ يَوْمَ الْقِيَامَةِ يَحْمِلُهُ عَلَى عُنُقِهِ إِنْ كَانَ بَعِيرًا جَاءَ بِهِ لَهُ ‏ ‏رُغَاءٌ ‏ ‏وَإِنْ كَانَتْ بَقَرَةً جَاءَ بِهَا لَهَا ‏ ‏خُوَارٌ ‏ ‏وَإِنْ كَانَتْ شَاةً جَاءَ بِهَا ‏ ‏تَيْعَرُ ‏ ‏فَقَدْ بَلَّغْتُ ‏ ‏قَالَ ‏ ‏أَبُو حُمَيْدٍ ‏ ‏ثُمَّ رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَيْهِ حَتَّى إِنَّا لَنَنْظُرُ إِلَى ‏ ‏عُفْرَةِ ‏ ‏إِبْطَيْهِ ‏ ‏قَالَ ‏ ‏أَبُو حُمَيْدٍ ‏ ‏وَقَدْ سَمِعَ ذَلِكَ مَعِي مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فَسَلُوهُ ‏","","",""],[1610,1610,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏وَمُجَالِدٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَكُمْ الْمُصَدِّقُ فَلَا ‏ ‏يَصْدُرَنَّ ‏ ‏عَنْكُمْ إِلَّا وَهُوَ رَاضٍ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[1611,1611,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُعَاذٍ الْأَشْهَلِيِّ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ يُقَالُ لَهَا ‏ ‏حَوَّاءُ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ يَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَ الْمُسْلِمَاتِ ‏ ‏لَا تَحْقِرَنَّ إِحْدَاكُنَّ لِجَارَتِهَا وَلَوْ كُرَاعُ شَاةٍ مُحَرَّقٌ ‏","","",""],[1612,1612,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ عَبْدِ اللَّهِ الْبَجَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏صَخْرِ بْنِ الْعَيْلَةِ ‏ ‏قَالَ ‏ ‏أُخِذَتْ عَمَّةُ ‏ ‏الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏فَقَدِمَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّتَهُ فَقَالَ ‏ ‏يَا ‏ ‏صَخْرُ ‏ ‏إِنَّ الْقَوْمَ إِذَا أَسْلَمُوا أَحْرَزُوا أَمْوَالَهُمْ وَدِمَاءَهُمْ فَادْفَعْهَا إِلَيْهِ وَكَانَ مَاءٌ ‏ ‏لِبَنِي سُلَيْمٍ ‏ ‏فَأَسْلَمُوا فَسَأَلُوهُ ذَلِكَ فَدَعَانِي فَقَالَ يَا ‏ ‏صَخْرُ ‏ ‏إِنَّ الْقَوْمَ إِذَا أَسْلَمُوا أَحْرَزُوا أَمْوَالَهُمْ وَدِمَاءَهُمْ فَادْفَعْهَا إِلَيْهِمْ فَدَفَعْتُهُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏صَخْرٍ ‏ ‏أَطْوَلَ مِنْ حَدِيثِ ‏ ‏أَبِي نُعَيْمٍ ‏","","",""],[1613,1613,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ يُونُسَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَصَدَّقَ امْرُؤٌ بِصَدَقَةٍ مِنْ كَسْبٍ طَيِّبٍ وَلَا يَقْبَلُ اللَّهُ إِلَّا طَيِّبًا إِلَّا وَضَعَهَا حِينَ يَضَعُهَا فِي كَفِّ الرَّحْمَنِ وَإِنَّ اللَّهَ ‏ ‏لَيُرَبِّي لِأَحَدِكُمْ التَّمْرَةَ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى تَكُونَ مِثْلَ ‏ ‏أُحُدٍ ‏","","",""],[1614,1614,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا نَقَصَتْ صَدَقَةٌ مِنْ مَالٍ وَمَا زَادَ اللَّهُ عَبْدًا بِعَفْوٍ إِلَّا عِزًّا وَمَا تَوَاضَعَ أَحَدٌ لِلَّهِ إِلَّا رَفَعَهُ اللَّهُ ‏","","",""],[1615,1615,"","","‏ ‏أَخْبَرَنَا ‏ ‏النَّضْرُ بْنُ شُمَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فِي كُلِّ إِبِلٍ ‏ ‏سَائِمَةٍ ‏ ‏فِي كُلِّ أَرْبَعِينَ ‏ ‏بِنْتُ لَبُونٍ ‏ ‏لَا تُفَرَّقُ إِبِلٌ عَنْ حِسَابِهَا مَنْ أَعْطَاهَا ‏ ‏مُؤْتَجِرًا ‏ ‏بِهَا فَلَهُ أَجْرُهَا وَمَنْ مَنَعَهَا فَإِنَّا آخِذُوهَا وَشَطْرَ إِبِلِهِ ‏ ‏عَزْمَةٌ ‏ ‏مِنْ ‏ ‏عَزَمَاتِ ‏ ‏اللَّهِ لَا يَحِلُّ لِآلِ ‏ ‏مُحَمَّدٍ ‏ ‏مِنْهَا شَيْءٌ ‏","","",""],[1616,1616,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏هَارُونَ بْنِ رِيَابٍ ‏ ‏حَدَّثَنِي ‏ ‏كِنَانَةُ بْنُ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ مُخَارِقٍ الْهِلَالِيِّ ‏ ‏قَالَ ‏ ‏تَحَمَّلْتُ ‏ ‏بِحَمَالَةٍ ‏ ‏فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْأَلُهُ فِيهَا فَقَالَ ‏ ‏أَقِمْ يَا ‏ ‏قَبِيصَةُ ‏ ‏حَتَّى تَأْتِيَنَا الصَّدَقَةُ فَنَأْمُرَ لَكَ بِهَا ثُمَّ قَالَ يَا ‏ ‏قَبِيصَةُ ‏ ‏إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ إِلَّا لِأَحَدِ ثَلَاثَةٍ رَجُلٍ تَحَمَّلَ ‏ ‏حَمَالَةً ‏ ‏فَحَلَّتْ لَهُ الْمَسْأَلَةُ فَسَأَلَ حَتَّى يُصِيبَهَا ثُمَّ يُمْسِكَ وَرَجُلٍ أَصَابَتْهُ ‏ ‏جَائِحَةٌ ‏ ‏فَاجْتَاحَتْ مَالَهُ فَحَلَّتْ لَهُ الْمَسْأَلَةُ فَسَأَلَ حَتَّى يُصِيبَ ‏ ‏قِوَامًا ‏ ‏مِنْ عَيْشٍ ‏ ‏أَوْ قَالَ سِدَادًا مِنْ عَيْشٍ ‏ ‏وَرَجُلٍ أَصَابَتْهُ ‏ ‏فَاقَةٌ ‏ ‏حَتَّى يَقُولَ ثَلَاثَةٌ مِنْ ذَوِي ‏ ‏الْحِجَى ‏ ‏مِنْ قَوْمِهِ قَدْ أَصَابَ فُلَانًا ‏ ‏الْفَاقَةُ ‏ ‏فَحَلَّتْ لَهُ الْمَسْأَلَةُ فَسَأَلَ حَتَّى يُصِيبَ ‏ ‏قِوَامًا ‏ ‏مِنْ عَيْشٍ ‏ ‏أَوْ سِدَادًا مِنْ عَيْشٍ ‏ ‏ثُمَّ يُمْسِكَ وَمَا سِوَاهُنَّ مِنْ الْمَسْأَلَةِ ‏ ‏سُحْتٌ ‏ ‏يَا ‏ ‏قَبِيصَةُ ‏ ‏يَأْكُلُهَا صَاحِبُهَا ‏ ‏سُحْتًا ‏","","",""],[1617,1617,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبَّادِ بْنِ الْعَوَّامِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ بَشِيرٍ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّدَقَاتِ أَيُّهَا أَفْضَلُ قَالَ ‏ ‏عَلَى ذِي الرَّحِمِ ‏ ‏الْكَاشِحِ ‏","","",""],[1618,1618,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو حَاتِمٍ الْبَصْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أُمِّ الرَّائِحِ بِنْتِ صُلَيْعٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏ذَكَرَ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الصَّدَقَةَ عَلَى الْمِسْكِينِ صَدَقَةٌ وَإِنَّهَا عَلَى ذِي الرَّحِمِ اثْنَتَانِ صَدَقَةٌ وَصِلَةٌ ‏","","",""],[1619,1619,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏قَالَ وَقَدْ سَمِعْتُهُ مِنَ ‏ ‏الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنْ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏يَرْفَعُهُ ‏ ‏قَالَ ‏ ‏الصَّدَقَةُ عَلَى الْمِسْكِينِ صَدَقَةٌ وَهِيَ عَلَى ذِي الرَّحِمِ اثْنَتَانِ صَدَقَةٌ وَصِلَةٌ ‏","","",""],[1620,1620,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏صِلَةَ بْنِ زُفَرَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏فَأُتِيَ بِشَاةٍ ‏ ‏مَصْلِيَّةٍ ‏ ‏فَقَالَ كُلُوا فَتَنَحَّى بَعْضُ الْقَوْمِ فَقَالَ إِنِّي صَائِمٌ ‏ ‏فَقَالَ ‏ ‏عَمَّارُ بْنُ يَاسِرٍ ‏ ‏مَنْ صَامَ الْيَوْمَ الَّذِي يُشَكُّ فِيهِ فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1621,1621,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ أَبِي صَغِيرَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏قَالَ ‏ ‏أَصْبَحْتُ فِي يَوْمٍ قَدْ أُشْكِلَ عَلَيَّ مِنْ شَعْبَانَ أَوْ مِنْ شَهْرِ رَمَضَانَ فَأَصْبَحْتُ صَائِمًا فَأَتَيْتُ ‏ ‏عِكْرِمَةَ ‏ ‏فَإِذَا هُوَ يَأْكُلُ خُبْزًا وَبَقْلًا فَقَالَ هَلُمَّ إِلَى الْغَدَاءِ فَقُلْتُ إِنِّي صَائِمٌ فَقَالَ أُقْسِمُ بِاللَّهِ لَتُفْطِرَنَّ فَلَمَّا رَأَيْتُهُ حَلَفَ وَلَا ‏ ‏يَسْتَثْنِي ‏ ‏تَقَدَّمْتُ ‏ ‏فَعَذَّرْتُ ‏ ‏وَإِنَّمَا تَسَحَّرْتُ قُبَيْلَ ذَلِكَ ثُمَّ قُلْتُ هَاتِ الْآنَ مَا عِنْدَكَ ‏ ‏فَقَالَ حَدَّثَنَا ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ حَالَ بَيْنَكُمْ وَبَيْنَهُ سَحَابٌ فَكَمِّلُوا الْعِدَّةَ ثَلَاثِينَ وَلَا تَسْتَقْبِلُوا الشَّهْرَ اسْتِقْبَالًا ‏","","",""],[1622,1622,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَكَرَ رَمَضَانَ فَقَالَ ‏ ‏لَا تَصُومُوا حَتَّى تَرَوْا الْهِلَالَ وَلَا تُفْطِرُوا حَتَّى تَرَوْهُ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ ‏ ‏فَاقْدُرُوا ‏ ‏لَهُ ‏","","",""],[1623,1623,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ الشَّهْرُ فَعُدُّوا ثَلَاثِينَ ‏","","",""],[1624,1624,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ عَجِبَ مِمَّنْ يَتَقَدَّمُ الشَّهْرَ وَيَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمُوهُ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَأَكْمِلُوا الْعِدَّةَ ثَلَاثِينَ ‏","","",""],[1625,1625,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ بْنِ إِبْرَاهِيمَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَمِّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى الْهِلَالَ قَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ وَالتَّوْفِيقِ لِمَا يُحِبُّ رَبُّنَا ‏ ‏وَيَرْضَى رَبُّنَا وَرَبُّكَ اللَّهُ ‏","","",""],[1626,1626,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الرِّفَاعِيُّ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَقَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ سُفْيَانَ الْمَدَنِيُّ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ يَحْيَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَى الْهِلَالَ قَالَ ‏ ‏اللَّهُمَّ أَهِلَّهُ عَلَيْنَا بِالْأَمْنِ وَالْإِيمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ رَبِّي وَرَبُّكَ اللَّهُ ‏","","",""],[1627,1627,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَدَّمُوا قَبْلَ رَمَضَانَ يَوْمًا وَلَا يَوْمَيْنِ إِلَّا أَنْ يَكُونَ رَجُلًا كَانَ يَصُومُ صَوْمًا فَلْيَصُمْهُ ‏","","",""],[1628,1628,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الشَّهْرُ تِسْعٌ وَعِشْرُونَ فَلَا تَصُومُوا حَتَّى تَرَوْهُ وَلَا تُفْطِرُوا حَتَّى تَرَوْهُ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ ‏ ‏فَاقْدُرُوا ‏ ‏لَهُ ‏","","",""],[1629,1629,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏تَرَاءَى النَّاسُ الْهِلَالَ فَأَخْبَرْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنِّي رَأَيْتُهُ فَصَامَ وَأَمَرَ النَّاسَ بِالصِّيَامِ ‏","","",""],[1630,1630,"","","‏ ‏حَدَّثَنِي ‏ ‏عِصْمَةُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ إِنِّي رَأَيْتُ الْهِلَالَ فَقَالَ ‏ ‏أَتَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ قَالَ نَعَمْ قَالَ يَا ‏ ‏بِلَالُ ‏ ‏نَادِ فِي النَّاسِ فَلْيَصُومُوا غَدًا ‏","","",""],[1631,1631,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَصْحَابُ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الرَّجُلُ صَائِمًا فَحَضَرَ الْإِفْطَارُ فَنَامَ قَبْلَ أَنْ يُفْطِرَ لَمْ يَأْكُلْ لَيْلَتَهُ وَلَا يَوْمَهُ حَتَّى يُمْسِيَ وَإِنَّ ‏ ‏قَيْسَ بْنَ صِرْمَةَ الْأَنْصَارِيَّ ‏ ‏كَانَ صَائِمًا فَلَمَّا حَضَرَ الْإِفْطَارُ أَتَى امْرَأَتَهُ فَقَالَ عِنْدَكِ طَعَامٌ فَقَالَتْ لَا وَلَكِنْ أَنْطَلِقُ فَأَطْلُبُ لَكَ وَكَانَ يَوْمَهُ يَعْمَلُ فَغَلَبَتْهُ عَيْنُهُ وَجَاءَتْ امْرَأَتُهُ فَلَمَّا رَأَتْهُ قَالَتْ خَيْبَةً لَكَ فَلَمَّا انْتَصَفَ النَّهَارُ غُشِيَ عَلَيْهِ فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ ‏ ‏الرَّفَثُ ‏ ‏إِلَى نِسَائِكُمْ ‏} ‏فَفَرِحُوا بِهَا فَرَحًا شَدِيدًا ‏ { ‏وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمْ ‏ ‏الْخَيْطُ الْأَبْيَضُ ‏ ‏مِنْ ‏ ‏الْخَيْطِ الْأَسْوَدِ ‏ }","","",""],[1632,1632,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ حَاتِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ لَقَدْ جَعَلْتُ تَحْتَ وِسَادَتِي خَيْطًا أَبْيَضَ وَخَيْطًا أَسْوَدَ فَمَا تَبَيَّنَ لِي شَيْءٌ قَالَ ‏ ‏إِنَّكَ لَعَرِيضُ ‏ ‏الْوِسَادِ ‏ ‏وَإِنَّمَا ذَلِكَ اللَّيْلُ مِنْ النَّهَارِ فِي قَوْلِهِ ‏ { ‏وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمْ ‏ ‏الْخَيْطُ الْأَبْيَضُ ‏ ‏مِنْ ‏ ‏الْخَيْطِ الْأَسْوَدِ ‏ ‏مِنْ الْفَجْرِ ‏}","","",""],[1633,1633,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ قَامَ إِلَى الصَّلَاةِ قَالَ قُلْتُ كَمْ كَانَ بَيْنَ الْأَذَانِ وَالسُّحُورِ قَالَ قَدْرُ قِرَاءَةِ خَمْسِينَ آيَةً ‏","","",""],[1634,1634,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السُّحُورِ بَرَكَةً ‏","","",""],[1635,1635,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُلَيٍّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي قَيْسٍ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏يَأْمُرُنَا أَنْ نَصْنَعَ لَهُ الطَّعَامَ يَتَسَحَّرُ بِهِ فَلَا يُصِيبُ مِنْهُ كَثِيرًا فَقُلْنَا لَهُ تَأْمُرُنَا بِهِ وَلَا تُصِيبُ مِنْهُ كَثِيرًا قَالَ إِنِّي لَا آمُرُكُمْ بِهِ أَنِّي ‏ ‏أَشْتَهِيهِ وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَصْلُ مَا بَيْنَ صِيَامِنَا وَصِيَامِ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏أَكْلَةُ السَّحَرِ ‏","","",""],[1636,1636,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ شُرَحْبِيلَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَمْ ‏ ‏يُبَيِّتْ ‏ ‏الصِّيَامَ قَبْلَ الْفَجْرِ فَلَا صِيَامَ لَهُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏فِي فَرْضِ الْوَاجِبِ أَقُولُ بِهِ ‏","","",""],[1637,1637,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ النَّاسُ بِخَيْرٍ مَا عَجَّلُوا الْفِطْرَ ‏","","",""],[1638,1638,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَقْبَلَ اللَّيْلُ وَأَدْبَرَ النَّهَارُ وَغَابَتْ الشَّمْسُ فَقَدْ أَفْطَرْتَ ‏","","",""],[1639,1639,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏الرَّبَابِ الضَّبِّيَّةِ ‏ ‏عَنْ ‏ ‏عَمِّهَا ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّ الْمَاءَ طَهُورٌ ‏","","",""],[1640,1640,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَطَّرَ صَائِمًا كُتِبَ لَهُ مِثْلُ أَجْرِهِ إِلَّا أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ الصَّائِمِ ‏","","",""],[1641,1641,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِيَّاكُمْ ‏ ‏وَالْوِصَالَ ‏ ‏مَرَّتَيْنِ قَالُوا فَإِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""],[1642,1642,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏قِيلَ إِنَّكَ تَفْعَلُ ذَاكَ قَالَ ‏ ‏إِنِّي لَسْتُ كَأَحَدِكُمْ إِنِّي أُطْعَمُ وَأُسْقَى ‏","","",""],[1643,1643,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏فَأَيُّكُمْ يُرِيدُ أَنْ ‏ ‏يُوَاصِلَ ‏ ‏فَلْيُوَاصِلْ ‏ ‏إِلَى السَّحَرِ قَالُوا إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ إِنِّي أَبِيتُ لِي مُطْعِمٌ يُطْعِمُنِي وَيَسْقِينِي ‏","","",""],[1644,1644,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْوِصَالِ ‏ ‏فَقَالَ لَهُ رِجَالٌ مِنْ الْمُسْلِمِينَ فَإِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَسْتُ مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي فَلَمَّا أَبَوْا أَنْ يَنْتَهُوا عَنْ ‏ ‏الْوِصَالِ ‏ ‏وَاصَلَ ‏ ‏بِهِمْ يَوْمًا ثُمَّ يَوْمًا ثُمَّ رَأَوْا الْهِلَالَ فَقَالَ لَوْ تَأَخَّرَ لَزِدْتُكُمْ ‏ ‏كَالْمُنَكِّلِ ‏ ‏لَهُمْ حِينَ أَبَوْا أَنْ يَنْتَهُوا ‏","","",""],[1645,1645,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏حَمْزَةَ بْنَ عَمْرٍو الْأَسْلَمِيَّ ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ السَّفَرَ فَمَا تَأْمُرُنِي قَالَ ‏ ‏إِنْ شِئْتَ فَصُمْ وَإِنْ شِئْتَ فَأَفْطِرْ ‏","","",""],[1646,1646,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فَصَامَ وَصَامَ النَّاسُ حَتَّى بَلَغَ ‏ ‏الْكَدِيدَ ‏ ‏ثُمَّ أَفْطَرَ فَأَفْطَرَ النَّاسُ فَكَانُوا يَأْخُذُونَ بِالْأَحْدَثِ فَالْأَحْدَثِ مِنْ فِعْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1647,1647,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏وَأَبُو الْوَلِيدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَمْرِو بْنِ الْحَسَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ ذَكَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ فِي سَفَرٍ فَرَأَى زِحَامًا وَرَجُلٌ قَدْ ظُلِّلَ عَلَيْهِ فَقَالَ مَا هَذَا قَالُوا هَذَا صَائِمٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنْ الْبِرِّ الصَّوْمُ فِي السَّفَرِ ‏","","",""],[1648,1648,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنْ الْبِرِّ الصِّيَامُ فِي السَّفَرِ ‏","","",""],[1649,1649,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏كَعْبِ بْنِ عَاصِمٍ الْأَشْعَرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ مِنْ الْبِرِّ الصِّيَامُ فِي السَّفَرِ ‏","","",""],[1650,1650,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَيَّةَ الضَّمْرِيِّ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ سَفَرٍ فَسَلَّمْتُ عَلَيْهِ فَلَمَّا ذَهَبْتُ لِأَخْرُجَ قَالَ انْتَظِرْ الْغَدَاءَ يَا ‏ ‏أَبَا أُمَيَّةَ ‏ ‏قَالَ فَقُلْتُ إِنِّي صَائِمٌ يَا نَبِيَّ اللَّهِ فَقَالَ ‏ ‏تَعَالَ أُخْبِرْكَ عَنْ الْمُسَافِرِ إِنَّ اللَّهَ وَضَعَ عَنْهُ الصِّيَامَ وَنِصْفَ الصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏إِنْ شَاءَ صَامَ وَإِنْ شَاءَ أَفْطَرَ ‏","","",""],[1651,1651,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏كُلَيْبَ بْنَ ذُهْلٍ الْحَضْرَمِيَّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عُبَيْدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏رَكِبْتُ مَعَ ‏ ‏أَبِي بَصْرَةَ الْغِفَارِيِّ ‏ ‏سَفِينَةً مِنْ ‏ ‏الْفُسْطَاطِ ‏ ‏فِي رَمَضَانَ فَدَفَعَ فَقَرَّبَ غَدَاءَهُ ثُمَّ قَالَ اقْتَرِبْ فَقُلْتُ أَلَسْتَ ‏ ‏تَرَى الْبُيُوتَ ‏ ‏فَقَالَ ‏ ‏أَبُو بَصْرَةَ ‏ ‏أَرَغِبْتَ عَنْ سُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1652,1652,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا مِنْ شَهْرِ رَمَضَانَ مِنْ غَيْرِ رُخْصَةٍ وَلَا مَرَضٍ فَلَنْ يَقْضِيَهُ صِيَامُ الدَّهْرِ كُلِّهِ وَلَوْ صَامَ الدَّهْرَ ‏","","",""],[1653,1653,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَارَةَ بْنَ عُمَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الْمُطَوِّسِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَفْطَرَ يَوْمًا مِنْ رَمَضَانَ مِنْ غَيْرِ رُخْصَةٍ رَخَّصَهُ اللَّهُ لَهُ لَمْ يَقْضِ عَنْهُ صِيَامُ الدَّهْرِ ‏","","",""],[1654,1654,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ ‏ ‏فَقَالَ هَلَكْتُ فَقَالَ ‏ ‏وَمَا أَهْلَكَكَ قَالَ ‏ ‏وَاقَعْتُ ‏ ‏امْرَأَتِي فِي شَهْرِ رَمَضَانَ قَالَ فَأَعْتِقْ رَقَبَةً قَالَ لَيْسَ عِنْدِي قَالَ فَصُمْ شَهْرَيْنِ مُتَتَابِعَيْنِ قَالَ لَا أَسْتَطِيعُ قَالَ فَأَطْعِمْ سِتِّينَ مِسْكِينًا قَالَ لَا أَجِدُ قَالَ فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَقٍ ‏ ‏فِيهِ تَمْرٌ فَقَالَ أَيْنَ السَّائِلُ تَصَدَّقْ بِهَذَا فَقَالَ أَعَلَى أَفْقَرَ مِنْ أَهْلِي يَا رَسُولَ اللَّهِ فَوَاللَّهِ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏ ‏أَهْلُ بَيْتٍ أَفْقَرَ مِنَّا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْتُمْ إِذًا وَضَحِكَ حَتَّى بَدَتْ أَنْيَابُهُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏أَفْطَرَ فِي رَمَضَانَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[1655,1655,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ الْأَنْصَارِيَّ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏مُحَمَّدَ بْنَ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏عَبَّادَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏إِنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ احْتَرَقَ فَسَأَلَهُ مَا لَهُ فَقَالَ أَصَابَ أَهْلَهُ فِي رَمَضَانَ فَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِكْتَلٍ يُدْعَى ‏ ‏الْعَرَقَ ‏ ‏فِيهِ تَمْرٌ فَقَالَ ‏ ‏أَيْنَ الْمُحْتَرِقُ فَقَامَ الرَّجُلُ فَقَالَ تَصَدَّقْ بِهَذَا ‏","","",""],[1656,1656,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لِامْرَأَةٍ ‏ ‏لَا تَصُومِي إِلَّا بِإِذْنِهِ ‏","","",""],[1657,1657,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُ الْمَرْأَةُ يَوْمًا تَطَوُّعًا فِي غَيْرِ رَمَضَانَ وَزَوْجُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ ‏","","",""],[1658,1658,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُ الْمَرْأَةُ يَوْمًا وَزَوْجُهَا شَاهِدٌ إِلَّا بِإِذْنِهِ ‏ ‏مَعْنَاهُ قَالَ فِي النُّذُورِ تَفِي بِهِ ‏","","",""],[1659,1659,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُ وَهُوَ صَائِمٌ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏أَمَا إِنَّهَا لَا تَدْعُو إِلَى خَيْرٍ ‏","","",""],[1660,1660,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعْدُ بْنُ حَفْصٍ الطَّلْحِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُقَبِّلُهَا وَهُوَ صَائِمٌ ‏","","",""],[1661,1661,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏هَشِشْتُ ‏ ‏فَقَبَّلْتُ وَأَنَا صَائِمٌ فَجِئْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ إِنِّي صَنَعْتُ الْيَوْمَ أَمْرًا عَظِيمًا قَبَّلْتُ وَأَنَا صَائِمٌ قَالَ ‏ ‏أَرَأَيْتَ لَوْ مَضْمَضْتَ مِنْ الْمَاءِ قُلْتُ إِذًا لَا يَضِيرُ قَالَ فَفِيمَ ‏","","",""],[1662,1662,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ يَعْنِي ابْنَ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏وَعَائِشَةَ ‏ ‏أَخْبَرتَاهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ أَهْلِهِ ثُمَّ يَصُومُ ‏","","",""],[1663,1663,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَسِيَ وَهُوَ صَائِمٌ فَأَكَلَ أَوْ شَرِبَ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏","","",""],[1664,1664,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو جَعْفَرٍ مُحَمَّدُ بْنُ مِهْرَانَ الْجَمَّالُ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي ذُبَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ أَوْ شَرِبَ نَاسِيًا وَهُوَ صَائِمٌ ثُمَّ ذَكَرَ فَلْيُتِمَّ صِيَامَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَهْلُ ‏ ‏الْحِجَازِ ‏ ‏يَقُولُونَ يَقْضِي وَأَنَا أَقُولُ لَا يَقْضِي ‏","","",""],[1665,1665,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ ‏ ‏قَالَ فَلَقِيتُ ‏ ‏ثَوْبَانَ ‏ ‏بِمَسْجِدِ ‏ ‏دِمَشْقَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ ‏ ‏فَقَالَ ‏ ‏صَدَقَ أَنَا صَبَبْتُ لَهُ الْوَضُوءَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏إِذَا ‏ ‏اسْتَقَاءَ ‏","","",""],[1666,1666,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏ذَرَعَ ‏ ‏الصَّائِمَ الْقَيْءُ وَهُوَ لَا يُرِيدُهُ فَلَا قَضَاءَ عَلَيْهِ وَإِذَا ‏ ‏اسْتَقَاءَ فَعَلَيْهِ الْقَضَاءُ ‏ ‏قَالَ ‏ ‏عِيسَى ‏ ‏زَعَمَ أَهْلُ ‏ ‏الْبَصْرَةِ ‏ ‏أَنَّ ‏ ‏هِشَامًا ‏ ‏أَوْهَمَ فِيهِ فَمَوْضِعُ الْخِلَافِ هَا هُنَا ‏","","",""],[1667,1667,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَمَانِ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ فَأَبْصَرَ رَجُلًا ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[1668,1668,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏أَنَّ ‏ ‏أَبَا أَسْمَاءَ الرَّحَبِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏ثَوْبَانَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي ‏ ‏بِالْبَقِيعِ ‏ ‏فَإِذَا رَجُلٌ ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَنَا ‏ ‏أَتَّقِي ‏ ‏الْحِجَامَةَ ‏ ‏فِي الصَّوْمِ فِي رَمَضَانَ ‏","","",""],[1669,1669,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏وَاصِلٍ ‏ ‏مَوْلَى ‏ ‏أَبِي عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏بَشَّارِ بْنِ أَبِي سَيْفٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ غُطَيْفٍ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏ ‏مَا لَمْ يَخْرِقْهَا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏يَعْنِي ‏ ‏بِالْغِيبَةِ ‏","","",""],[1670,1670,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ النُّعْمَانِ أَبُو النُّعْمَانِ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏وَكَانَ جَدِّي قَدْ أُتِيَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَسَحَ عَلَى رَأْسِهِ وَقَالَ ‏ ‏لَا تَكْتَحِلْ بِالنَّهَارِ وَأَنْتَ صَائِمٌ اكْتَحِلْ لَيْلًا بِالْإِثْمِدِ فَإِنَّهُ ‏ ‏يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعَرَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏لَا ‏ ‏أَرَى بِالْكُحْلِ بَأْسًا ‏","","",""],[1671,1671,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏بَكْرٌ هُوَ ابْنُ مُضَرَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏مَوْلَى ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏أَنَّهُ قَالَ لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ ‏} ‏قَالَ كَانَ مَنْ أَرَادَ أَنْ يُفْطِرَ وَيَفْتَدِيَ فَعَلَ حَتَّى نَزَلَتْ الْآيَةُ الَّتِي بَعْدَهَا ‏ ‏فَنَسَخَتْهَا ‏","","",""],[1672,1672,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏سِمَاكِ بْنِ حَرْبٍ ‏ ‏عَنْ ‏ ‏هَارُونَ ابْنِ ابْنَةِ أُمِّ هَانِئٍ ‏ ‏أَوْ ‏ ‏ابْنِ ابْنِ أُمِّ هَانِئٍ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَهِيَ صَائِمَةٌ فَأُتِيَ بِإِنَاءٍ فَشَرِبَ ثُمَّ نَاوَلَهَا فَشَرِبَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ قَضَاءَ رَمَضَانَ فَصُومِي يَوْمًا آخَرَ وَإِنْ كَانَ تَطَوُّعًا فَإِنْ شِئْتِ فَاقْضِيهِ وَإِنْ شِئْتِ فَلَا ‏ ‏تَقْضِيهِ ‏","","",""],[1673,1673,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أُمِّ هَانِئٍ ‏ ‏قَالَتْ ‏ ‏لَمَّا كَانَ يَوْمُ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏جَاءَتْ ‏ ‏فَاطِمَةُ ‏ ‏فَجَلَسَتْ عَنْ يَسَارِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُمُّ هَانِئٍ ‏ ‏عَنْ يَمِينِهِ قَالَتْ فَجَاءَتْ الْوَلِيدَةُ بِإِنَاءٍ فِيهِ شَرَابٌ فَنَاوَلَتْهُ فَشَرِبَ مِنْهُ ثُمَّ نَاوَلَهُ ‏ ‏أُمَّ هَانِئٍ ‏ ‏فَشَرِبَتْ مِنْهُ ثُمَّ قَالَتْ يَا رَسُولَ اللَّهِ لَقَدْ أَفْطَرْتُ وَكُنْتُ صَائِمَةً فَقَالَ لَهَا أَكُنْتِ تَقْضِينَ شَيْئًا قَالَتْ لَا قَالَ ‏ ‏فَلَا يَضُرُّكِ إِنْ كَانَ تَطَوُّعًا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏أَقُولُ بِهِ إِنْ شَاءَ قَضَى وَإِنْ شَاءَ لَمْ يَقْضِ ‏","","",""],[1674,1674,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دُعِيَ أَحَدُكُمْ إِلَى طَعَامٍ وَهُوَ صَائِمٌ فَلْيَقُلْ إِنِّي صَائِمٌ ‏","","",""],[1675,1675,"","","‏ ‏أَخْبَرَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبٍ الْأَنْصَارِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَوْلَاةً لَنَا يُقَالُ لَهَا ‏ ‏لَيْلَى ‏ ‏تُحَدِّثُ عَنْ ‏ ‏جَدَّتِهَا ‏ ‏أُمِّ عُمَارَةَ بِنْتِ كَعْبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا فَدَعَتْ لَهُ بِطَعَامٍ فَقَالَ لَهَا كُلِي فَقَالَتْ إِنِّي صَائِمَةٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الصَّائِمَ إِذَا أُكِلَ عِنْدَهُ صَلَّتْ عَلَيْهِ الْمَلَائِكَةُ حَتَّى يَفْرُغُوا وَرُبَّمَا قَالَ حَتَّى يَقْضُوا أَكْلَهُمْ ‏","","",""],[1676,1676,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَامَ شَهْرًا تَامًّا إِلَّا شَعْبَانَ فَإِنَّهُ كَانَ يَصِلُهُ بِرَمَضَانَ لِيَكُونَا شَهْرَيْنِ مُتَتَابِعَيْنِ وَكَانَ يَصُومُ مِنْ الشَّهْرِ حَتَّى نَقُولَ لَا يُفْطِرُ وَيُفْطِرُ حَتَّى نَقُولَ لَا يَصُومُ ‏","","",""],[1677,1677,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ الْحَنَفِيُّ ‏ ‏يُقَالُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ النِّصْفُ مِنْ شَعْبَانَ فَأَمْسِكُوا عَنْ الصَّوْمِ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏نَحْوَ هَذَا ‏","","",""],[1678,1678,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِرَجُلٍ ‏ ‏هَلْ صُمْتَ مِنْ سَرَرِ هَذَا الشَّهْرِ فَقَالَ لَا قَالَ فَإِذَا أَفْطَرْتَ مِنْ رَمَضَانَ فَصُمْ يَوْمَيْنِ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏سَرَرُهُ آخِرُهُ ‏","","",""],[1679,1679,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏مَا صَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا كَامِلًا غَيْرَ رَمَضَانَ وَإِنْ كَانَ لَيَصُومُ إِذَا صَامَ حَتَّى يَقُولَ الْقَائِلُ لَا وَاللَّهِ لَا يُفْطِرُ وَيُفْطِرُ إِذَا أَفْطَرَ حَتَّى يَقُولَ الْقَائِلُ لَا وَاللَّهِ لَا يَصُومُ ‏","","",""],[1680,1680,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ذُكِرَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ يَصُومُ الدَّهْرَ فَقَالَ ‏ ‏لَا صَامَ وَلَا أَفْطَرَ ‏","","",""],[1681,1681,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ أَبِي سُلَيْمَانَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏أَوْصَانِي خَلِيلِي بِثَلَاثٍ لَسْتُ بِتَارِكِهِنَّ ‏ ‏أَنْ لَا أَنَامَ إِلَّا عَلَى وِتْرٍ وَأَنْ أَصُومَ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ وَأَنْ لَا أَدَعَ رَكْعَتَيْ الضُّحَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبَّاسٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏نَحْوَهُ ‏","","",""],[1682,1682,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صِيَامُ الْبِيضِ ‏ ‏صِيَامُ الدَّهْرِ وَإِفْطَارُهُ ‏","","",""],[1683,1683,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جُبَيْرِ بْنِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِجَابِرٍ ‏ ‏أَنَهَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ يَوْمِ الْجُمُعَةِ قَالَ نَعَمْ وَرَبِّ هَذَا ‏ ‏الْبَيْتِ ‏","","",""],[1684,1684,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ بُسْرٍ ‏ ‏عَنْ ‏ ‏أُخْتِهِ ‏ ‏يُقَالُ لَهَا ‏ ‏الصَّمَّاءُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَصُومُوا يَوْمَ السَّبْتِ إِلَّا فِيمَا افْتُرِضَ عَلَيْكُمْ وَإِنْ لَمْ يَجِدْ أَحَدُكُمْ إِلَّا كَذَا أَوْ ‏ ‏لِحَاءَ ‏ ‏شَجَرَةٍ فَلْيَمْضَغْهُ ‏","","",""],[1685,1685,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏أَنَّ ‏ ‏مَوْلَى قُدَامَةَ بْنِ مَظْعُونٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏مَوْلَى أُسَامَةَ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏كَانَ ‏ ‏أُسَامَةُ ‏ ‏يَرْكَبُ إِلَى مَالٍ لَهُ ‏ ‏بِوَادِي الْقُرَى ‏ ‏فَيَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ فِي الطَّرِيقِ فَقُلْتُ لَهُ لِمَ تَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ فِي السَّفَرِ وَقَدْ كَبِرْتَ وَضَعُفْتَ ‏ ‏أَوْ ‏ ‏رَقِقْتَ ‏ ‏فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ وَقَالَ ‏ ‏إِنَّ أَعْمَالَ النَّاسِ تُعْرَضُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ ‏","","",""],[1686,1686,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ رِفَاعَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ فَسَأَلْتُهُ فَقَالَ ‏ ‏إِنَّ الْأَعْمَالَ تُعْرَضُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ ‏","","",""],[1687,1687,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏يَرْفَعُهُ ‏ ‏قَالَ ‏ ‏أَحَبُّ الصِّيَامِ إِلَى اللَّهِ عَزَّ وَجَلَّ صِيَامُ ‏ ‏دَاوُدَ ‏ ‏كَانَ يَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا وَأَحَبُّ الصَّلَاةِ إِلَى اللَّهِ عَزَّ وَجَلَّ صَلَاةُ ‏ ‏دَاوُدَ ‏ ‏كَانَ ‏ ‏يُصَلِّي نِصْفًا وَيَنَامُ ثُلُثًا وَيُسَبِّحُ سُدُسًا ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏هَذَا اللَّفْظُ الْأَخِيرُ غَلَطٌ أَوْ خَطَأٌ إِنَّمَا هُوَ أَنَّهُ كَانَ يَنَامُ نِصْفَ اللَّيْلِ وَيُصَلِّي ثُلُثَهُ وَيُسَبِّحُ تَسْبِيحَةً ‏","","",""],[1688,1688,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏قَزَعَةَ ‏ ‏مَوْلَى ‏ ‏زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا صَوْمَ يَوْمَيْنِ يَوْمَ الْفِطْرِ ‏ ‏وَيَوْمَ النَّحْرِ ‏","","",""],[1689,1689,"","","‏ ‏حَدَّثَنَا ‏ ‏نُعَيْمُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏وسَعْدُ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ ثُمَّ أَتْبَعَهُ سِتَّةً مِنْ شَوَّالٍ فَذَلِكَ صِيَامُ الدَّهْرِ ‏","","",""],[1690,1690,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ الْحَارِثِ الذِّمَارِيُّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صِيَامُ شَهْرٍ بِعَشَرَةِ أَشْهُرٍ وَسِتَّةِ أَيَّامٍ بَعْدَهُنَّ بِشَهْرَيْنِ فَذَلِكَ تَمَامُ سَنَةٍ ‏ ‏يَعْنِي شَهْرَ رَمَضَانَ وَسِتَّةَ أَيَّامٍ بَعْدَهُ ‏","","",""],[1691,1691,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏النُّعْمَانِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عَلِيٍّ ‏ ‏فَسَأَلَهُ عَنْ شَهْرٍ يَصُومُهُ ‏ ‏فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏مَا سَأَلَنِي أَحَدٌ عَنْ هَذَا بَعْدَ إِذْ سَمِعْتُ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ شَهْرٍ يَصُومُهُ مِنْ السَّنَةِ فَأَمَرَهُ بِصِيَامِ الْمُحَرَّمِ وَقَالَ ‏ ‏إِنَّ فِيهِ يَوْمًا تَابَ اللَّهُ عَلَى قَوْمٍ وَيَتُوبُ فِيهِ عَلَى قَوْمٍ ‏","","",""],[1692,1692,"","","‏ ‏أَخْبَرَنَا ‏ ‏زَيْدُ بْنُ عَوْفٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ شَهْرُ اللَّهِ الَّذِي تَدْعُونَهُ الْمُحَرَّمَ ‏","","",""],[1693,1693,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَأَخْبَرَنَا ‏ ‏يَحْيَى بْنُ حَسَّانَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ الْمُحَرَّمُ ‏","","",""],[1694,1694,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَالْيَهُودُ ‏ ‏يَصُومُونَ يَوْمَ عَاشُورَاءَ فَسَأَلَهُمْ فَقَالُوا هَذَا الْيَوْمُ الَّذِي ظَهَرَ فِيهِ ‏ ‏مُوسَى ‏ ‏عَلَى ‏ ‏فِرْعَوْنَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْتُمْ أَوْلَى ‏ ‏بِمُوسَى ‏ ‏فَصُومُوهُ ‏","","",""],[1695,1695,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ الْمَجِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ يَوْمَ عَاشُورَاءَ وَيَأْمُرُنَا بِصِيَامِهِ ‏","","",""],[1696,1696,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي عُبَيْدٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْأَكْوَعِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ يَوْمَ عَاشُورَاءَ رَجُلًا مِنْ ‏ ‏أَسْلَمَ ‏ ‏إِنَّ الْيَوْمَ يَوْمُ عَاشُورَاءَ فَمَنْ كَانَ أَكَلَ أَوْ شَرِبَ فَلْيُتِمَّ بَقِيَّةَ يَوْمِهِ وَمَنْ لَمْ يَكُنْ أَكَلَ أَوْ شَرِبَ فَلْيَصُمْهُ ‏","","",""],[1697,1697,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَعْلَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا يَوْمُ عَاشُورَاءَ كَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَصُومُهُ فِي الْجَاهِلِيَّةِ فَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَصُومَهُ فَلْيَصُمْهُ وَمَنْ أَحَبَّ مِنْكُمْ أَنْ يَتْرُكَهُ فَلْيَتْرُكْهُ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَا يَصُومُهُ إِلَّا أَنْ يُوَافِقَ صِيَامَهُ ‏","","",""],[1698,1698,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعَيْبُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ يَوْمُ عَاشُورَاءَ يَوْمًا تَصُومُهُ ‏ ‏قُرَيْشٌ ‏ ‏فِي الْجَاهِلِيَّةِ فَلَمَّا قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏صَامَهُ وَأَمَرَ بِصِيَامِهِ حَتَّى إِذَا فُرِضَ رَمَضَانُ كَانَ رَمَضَانُ هُوَ الْفَرِيضَةُ وَتُرِكَ يَوْمُ عَاشُورَاءَ فَمَنْ شَاءَ صَامَهُ وَمَنْ شَاءَ تَرَكَهُ ‏","","",""],[1699,1699,"","","‏ ‏أَخْبَرَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُلَيٍّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمُ ‏ ‏عَرَفَةَ ‏ ‏وَأَيَّامُ التَّشْرِيقِ عِيدُنَا أَهْلَ الْإِسْلَامِ وَهِيَ أَيَّامُ أَكْلٍ وَشُرْبٍ ‏","","",""],[1700,1700,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْمُعَلَّى بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ صَوْمِ يَوْمِ ‏ ‏عَرَفَةَ ‏ ‏فَقَالَ ‏ ‏حَجَجْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يَصُمْهُ وَحَجَجْتُ مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏فَلَمْ يَصُمْهُ وَحَجَجْتُ مَعَ ‏ ‏عُمَرَ ‏ ‏فَلَمْ يَصُمْهُ وَحَجَجْتُ مَعَ ‏ ‏عُثْمَانَ ‏ ‏فَلَمْ يَصُمْهُ وَأَنَا لَا أَصُومُهُ وَلَا آمُرُ بِهِ وَلَا أَنْهَى عَنْهُ ‏","","",""],[1701,1701,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ سُحَيْمٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ ‏ ‏أَوْ أَمَرَ رَجُلًا ‏ ‏يُنَادِي أَيَّامَ التَّشْرِيقِ ‏ ‏أَنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُؤْمِنٌ وَهِيَ أَيَّامُ أَكْلٍ وَشُرْبٍ ‏","","",""],[1702,1702,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي مُرَّةَ ‏ ‏مَوْلَى ‏ ‏عَقِيلٍ ‏ ‏أَنَّهُ دَخَلَ هُوَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَلَى ‏ ‏عَمْرِو بْنِ الْعَاصِ ‏ ‏وَذَلِكَ الْغَدَ أَوْ بَعْدَ الْغَدِ مِنْ يَوْمِ الْأَضْحَى فَقَرَّبَ إِلَيْهِمْ ‏ ‏عَمْرٌو ‏ ‏طَعَامًا فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنِّي صَائِمٌ ‏ ‏فَقَالَ ‏ ‏عَمْرٌو ‏ ‏أَفْطِرْ فَإِنَّ هَذِهِ الْأَيَّامَ الَّتِي كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا بِفِطْرِهَا وَيَنْهَانَا عَنْ صِيَامِهَا فَأَفْطَرَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَأَكَلَ وَأَكَلْتُ مَعَهُ ‏","","",""],[1703,1703,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً نَذَرَتْ أَنْ تَحُجَّ فَمَاتَتْ فَجَاءَ أَخُوهَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ عَنْ ذَلِكَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ عَلَيْهَا دَيْنٌ أَكُنْتَ قَاضِيَهُ قَالَ نَعَمْ قَالَ فَاقْضُوا اللَّهَ اللَّهُ أَحَقُّ بِالْوَفَاءِ قَالَ فَصَامَ عَنْهَا ‏","","",""],[1704,1704,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُلُوفُ ‏ ‏فَمِ الصَّائِمِ أَطْيَبُ عِنْدَ اللَّهِ مِنْ رِيحِ الْمِسْكِ وَلِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ عِنْدَ فِطْرِهِ وَفَرْحَةٌ يَوْمَ الْقِيَامَةِ ‏","","",""],[1705,1705,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ اللَّهُ تَعَالَى ‏ ‏كُلُّ عَمَلِ ابْنِ ‏ ‏آدَمَ ‏ ‏لَهُ فَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَّا الصِّيَامَ هُوَ لِي وَأَنَا أَجْزِي بِهِ إِنَّهُ يَتْرُكُ الطَّعَامَ وَشَهْوَتَهُ مِنْ أَجْلِي وَيَتْرُكُ الشَّرَابَ وَشَهْوَتَهُ مِنْ أَجْلِي فَهُوَ لِي وَأَنَا أَجْزِي بِهِ ‏","","",""],[1706,1706,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّوْمُ ‏ ‏جُنَّةٌ ‏","","",""],[1707,1707,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَفْطَرَ عِنْدَ أُنَاسٍ قَالَ ‏ ‏أَفْطَرَ عِنْدَكُمْ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمْ الْأَبْرَارُ وَتَنَزَّلَتْ عَلَيْكُمْ الْمَلَائِكَةُ ‏","","",""],[1708,1708,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُسْلِمًا الْبَطِينَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا الْعَمَلُ فِي أَيَّامٍ أَفْضَلَ مِنْ الْعَمَلِ فِي عَشْرِ ذِي الْحِجَّةِ قِيلَ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ إِلَّا رَجُلٌ خَرَجَ بِنَفْسِهِ وَمَالِهِ ثُمَّ لَمْ يَرْجِعْ بِشَيْءٍ ‏","","",""],[1709,1709,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏أَصْبَغُ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ عَمَلٍ أَزْكَى عِنْدَ اللَّهِ عَزَّ وَجَلَّ وَلَا أَعْظَمَ أَجْرًا مِنْ خَيْرٍ تَعْمَلُهُ فِي عَشْرِ الْأَضْحَى قِيلَ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ قَالَ وَلَا الْجِهَادُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ إِلَّا رَجُلٌ خَرَجَ بِنَفْسِهِ وَمَالِهِ فَلَمْ يَرْجِعْ مِنْ ذَلِكَ بِشَيْءٍ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏سَعِيدُ بْنُ جُبَيْرٍ ‏ ‏إِذَا دَخَلَ أَيَّامُ الْعَشْرِ اجْتَهَدَ اجْتِهَادًا شَدِيدًا حَتَّى مَا يَكَادُ يَقْدِرُ عَلَيْهِ ‏","","",""],[1710,1710,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ رَمَضَانُ فُتِحَتْ أَبْوَابُ السَّمَاءِ وَغُلِّقَتْ أَبْوَابُ النَّارِ ‏ ‏وَصُفِّدَتْ ‏ ‏الشَّيَاطِينُ ‏","","",""],[1711,1711,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[1712,1712,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏صُمْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرَ رَمَضَانَ قَالَ فَلَمْ يَقُمْ بِنَا مِنْ الشَّهْرِ شَيْئًا حَتَّى بَقِيَ سَبْعٌ قَالَ فَقَامَ بِنَا حَتَّى ذَهَبَ ثُلُثُ اللَّيْلِ قَالَ فَلَمَّا كَانَتْ السَّادِسَةُ لَمْ يَقُمْ بِنَا فَلَمَّا كَانَتْ الْخَامِسَةُ قَامَ بِنَا حَتَّى ذَهَبَ شَطْرُ اللَّيْلِ الْآخِرُ قُلْنَا يَا رَسُولَ اللَّهِ لَوْ نَفَّلْتَنَا بَقِيَّةَ هَذِهِ اللَّيْلَةِ فَقَالَ ‏ ‏إِنَّ الرَّجُلَ إِذَا قَامَ مَعَ الْإِمَامِ حَتَّى يَنْصَرِفَ مِنْ صَلَاتِهِ حُسِبَ لَهُ قِيَامُ لَيْلَتِهِ فَلَمَّا كَانَتْ الرَّابِعَةُ لَمْ يَقُمْ بِنَا فَلَمَّا كَانَتْ الثَّالِثَةُ جَمَعَ أَهْلَهُ وَنِسَاءَهُ وَالنَّاسَ فَقَامَ بِنَا حَتَّى خَشِينَا أَنْ يَفُوتَنَا الْفَلَاحُ قُلْنَا وَمَا الْفَلَاحُ قَالَ السُّحُورُ قَالَ ثُمَّ لَمْ يَقُمْ بِنَا بَقِيَّةَ الشَّهْرِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْجُرَشِيِّ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏نَحْوَهُ ‏","","",""],[1713,1713,"","","‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي حَصِينٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْتَكِفُ ‏ ‏الْعَشْرَ الْأَوَاخِرَ فَلَمَّا كَانَ الْعَامُ الَّذِي قُبِضَ فِيهِ ‏ ‏اعْتَكَفَ ‏ ‏عِشْرِينَ يَوْمًا ‏","","",""],[1714,1714,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعَيْبُ بْنُ أَبِي حَمْزَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏أَنَّ ‏ ‏صَفِّيَةَ بِنْتَ حُيَيٍّ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهَا ‏ ‏جَاءَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَزُورُهُ فِي ‏ ‏اعْتِكَافِهِ ‏ ‏فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ فَتَحَدَّثَتْ عِنْدَهُ سَاعَةً ثُمَّ قَامَتْ ‏","","",""],[1715,1715,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏عُبَادَةَ بْنِ الصَّامِتِ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُرِيدُ أَنْ يُخْبِرَنَا بِلَيْلَةِ الْقَدْرِ فَتَلَاحَى رَجُلَانِ مِنْ الْمُسْلِمِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي خَرَجْتُ إِلَيْكُمْ وَأَنَا أُرِيدُ أَنْ أُخْبِرَكُمْ بِلَيْلَةِ الْقَدْرِ وَكَانَ بَيْنَ فُلَانٍ وَفُلَانٍ لِحَاءٌ فَرُفِعَتْ وَعَسَى أَنْ يَكُونَ خَيْرًا فَالْتَمِسُوهَا فِي الْعَشْرِ الْأَوَاخِرِ فِي الْخَامِسَةِ وَالسَّابِعَةِ وَالتَّاسِعَةِ ‏","","",""],[1716,1716,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ وَقَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُرِيتُ لَيْلَةَ الْقَدْرِ ثُمَّ أَيْقَظَنِي بَعْضُ أَهْلِي فَنَسِيتُهَا فَالْتَمِسُوهَا فِي الْعَشْرِ ‏ ‏الْغَوَابِرِ ‏","","",""],[1717,1717,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سَالِمُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْتَمِسُوا لَيْلَةَ الْقَدْرِ فِي السَّبْعِ الْأَوَاخِرِ ‏","","",""],[1718,1718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَمْرٍو الْفُقَيْمِيُّ ‏ ‏عَنْ ‏ ‏مِهْرَانَ أَبِي صَفْوَانَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَرَادَ الْحَجَّ فَلْيَتَعَجَّلْ ‏","","",""],[1719,1719,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ لَمْ يَمْنَعْهُ عَنْ الْحَجِّ حَاجَةٌ ظَاهِرَةٌ أَوْ سُلْطَانٌ جَائِرٌ أَوْ مَرَضٌ حَابِسٌ فَمَاتَ وَلَمْ يَحُجَّ فَلْيَمُتْ إِنْ شَاءَ يَهُودِيًّا وَإِنْ شَاءَ نَصْرَانِيًّا ‏","","",""],[1720,1720,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُجَاهِدُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ أَرْقَمَ ‏ ‏يَقُولُ ‏ ‏حَجَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ هِجْرَتِهِ حَجَّةً ‏ ‏قَالَ وَقَالَ ‏ ‏أَبُو إِسْحَقَ ‏ ‏حَجَّ قَبْلَ هِجْرَتِهِ حَجَّةً ‏","","",""],[1721,1721,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَمْ حَجَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّةً وَاحِدَةً وَاعْتَمَرَ أَرْبَعًا عُمْرَتُهُ الْأُولَى الَّتِي صَدَّهُ الْمُشْرِكُونَ عَنْ ‏ ‏الْبَيْتِ ‏ ‏وَعُمْرَتُهُ الثَّانِيَةُ حِينَ صَالَحُوهُ فَرَجَعَ مِنْ الْعَامِ الْمُقْبِلِ وَعُمْرَتُهُ مِنْ ‏ ‏الْجِعْرَانَةِ ‏ ‏حِينَ قَسَّمَ غَنِيمَةَ ‏ ‏حُنَيْنٍ ‏ ‏فِي ذِي الْقَعْدَةِ وَعُمْرَتُهُ مَعَ حَجَّتِهِ ‏","","",""],[1722,1722,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ كَثِيرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سِنَانٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُتِبَ عَلَيْكُمْ الْحَجُّ فَقِيلَ يَا رَسُولَ اللَّهِ فِي كُلِّ عَامٍ قَالَ لَا وَلَوْ قُلْتُهَا لَوَجَبَتْ الْحَجُّ مَرَّةٌ فَمَا زَادَ فَهُوَ تَطَوُّعٌ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏نَحْوَهُ ‏","","",""],[1723,1723,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏وَقَّتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنًا ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَمَّا هَذِهِ الثَّلَاثُ فَإِنِّي سَمِعْتُهُنَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبَلَغَنِي أَنَّهُ وَقَّتَ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏يَلَمْلَمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏مِثْلَهُ ‏","","",""],[1724,1724,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسْلِمُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَّتَ لِأَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏وَلِأَهْلِ ‏ ‏الشَّامِ ‏ ‏الْجُحْفَةَ ‏ ‏وَلِأَهْلِ ‏ ‏نَجْدٍ ‏ ‏قَرْنَ الْمَنَازِلِ ‏ ‏وَلِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏أَلَمْلَمَ ‏ ‏هُنَّ لِأَهْلِهِنَّ وَلِكُلِّ آتٍ أَتَى عَلَيْهِنَّ مِنْ غَيْرِهِنَّ مَنْ أَرَادَ الْحَجَّ وَالْعُمْرَةَ وَمَنْ كَانَ دُونَ ذَلِكَ فَمِنْ حَيْثُ أَنْشَأَ حَتَّى أَهْلُ ‏ ‏مَكَّةَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏","","",""],[1725,1725,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏امْتَرَى ‏ ‏الْمِسْوَرُ بْنُ مَخْرَمَةَ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏فِي غَسْلِ الْمُحْرِمِ رَأْسَهُ فَأَرْسَلُونِي إِلَى ‏ ‏أَبِي أَيُّوبَ الْأَنْصَارِيِّ ‏ ‏كَيْفَ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْسِلُ رَأْسَهُ وَهُوَ مُحْرِمٌ فَأَتَيْتُ ‏ ‏أَبَا أَيُّوبَ ‏ ‏وَهُوَ بَيْنَ قَرْنَيْ الْبِئْرِ وَقَدْ سُتِرَ عَلَيْهِ بِثَوْبٍ فَسَلَّمْتُ عَلَيْهِ فَضَمَّ الثَّوْبَ إِلَيْهِ فَقُلْتُ أَرْسَلَنِي إِلَيْكَ ابْنُ أَخِيكَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏كَيْفَ رَأَيْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْسِلُ رَأْسَهُ فَأَمَرَّ يَدَيْهِ عَلَى رَأْسِهِ مُقْبِلًا وَمُدْبِرًا ‏","","",""],[1726,1726,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَعْقُوبَ الْمَدَنِيُّ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدِ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَجَرَّدَ لِلْإِهْلَالِ وَاغْتَسَلَ ‏","","",""],[1727,1727,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَجَّةٌ مَبْرُورَةٌ لَيْسَ لَهَا ثَوَابٌ إِلَّا الْجَنَّةُ وَعُمْرَتَانِ تُكَفِّرَانِ مَا بَيْنَهُمَا مِنْ الذُّنُوبِ ‏","","",""],[1728,1728,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَازِمٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ حَجَّ ‏ ‏الْبَيْتَ ‏ ‏فَلَمْ ‏ ‏يَرْفُثْ ‏ ‏وَلَمْ يَفْسُقْ رَجَعَ كَمَا وَلَدَتْهُ أُمُّهُ ‏","","",""],[1729,1729,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏عَنْ ‏ ‏الضَّحَّاكِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَرْبُوعٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْحَجِّ أَفْضَلُ قَالَ ‏ ‏الْعَجُّ وَالثَّجُّ ‏ ‏الْعَجُّ ‏ ‏يَعْنِي التَّلْبِيَةَ وَالثَّجُّ ‏ ‏يَعْنِي إِهْرَاقَةَ الدَّمِ ‏","","",""],[1730,1730,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏هُوَ ‏ ‏ابْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا نَلْبَسُ مِنْ الثِّيَابِ إِذَا أَحْرَمْنَا قَالَ ‏ ‏لَا تَلْبَسُوا الْقُمُصَ وَلَا السَّرَاوِيلَاتِ وَلَا الْعَمَائِمَ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا الْخِفَافَ إِلَّا أَنْ يَكُونَ أَحَدٌ لَيْسَتْ لَهُ نَعْلَانِ فَلْيَلْبَسْ الْخُفَّيْنِ وَلْيَجْعَلْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا تَلْبَسُوا مِنْ الثِّيَابِ شَيْئًا مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏وَلَا زَعْفَرَانٌ ‏","","",""],[1731,1731,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ لَمْ يَجِدْ إِزَارًا فَلْيَلْبَسْ سَرَاوِيلَ وَمَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ قَالَ قُلْتُ ‏ ‏أَوْ قِيلَ أَيَقْطَعُهُمَا ‏ ‏قَالَ لَا ‏","","",""],[1732,1732,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّا يَلْبَسُ الْمُحْرِمُ قَالَ ‏ ‏لَا يَلْبَسُ الْقُمُصَ وَلَا الْعَمَائِمَ وَلَا السَّرَاوِيلَاتِ وَلَا ‏ ‏الْبَرَانِسَ ‏ ‏وَلَا الْخِفَافَ إِلَّا أَنْ لَا يَجِدَ نَعْلَيْنِ فَيَلْبَسَ خُفَّيْنِ وَيَقْطَعَهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[1733,1733,"","","‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَبْلَ أَنْ يُحْرِمَ بِأَطْيَبِ الطِّيبِ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عُرْوَةُ ‏ ‏يَقُولُ لَنَا ‏ ‏تَطَيَّبُوا قَبْلَ أَنْ تُحْرِمُوا وَقَبْلَ أَنْ تُفِيضُوا ‏ ‏يَوْمَ النَّحْرِ ‏","","",""],[1734,1734,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ إِحْرَامِهِ بِأَطْيَبِ مَا أَجِدُهُ ‏","","",""],[1735,1735,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَجَعْفَرُ بْنُ عَوْنٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏تَقُولُ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحُرْمِهِ وَطَيَّبْتُهُ ‏ ‏بِمِنًى ‏ ‏قَبْلَ أَنْ يُفِيضَ ‏","","",""],[1736,1736,"","","‏ ‏حَدَّثَنِي ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏نُفِسَتْ ‏ ‏أَسْمَاءُ ‏ ‏بِمُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏بِالشَّجَرَةِ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ تَغْتَسِلَ ‏ ‏وَتُهِلَّ ‏","","",""],[1737,1737,"","","‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏فِي حَدِيثِ ‏ ‏أَسْمَاءَ بِنْتِ عُمَيْسٍ ‏ ‏حِينَ نُفِسَتْ ‏ ‏بِذِي الْحُلَيْفَةِ ‏ ‏فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبَا بَكْرٍ ‏ ‏أَنْ يَأْمُرَهَا أَنْ تَغْتَسِلَ ‏ ‏وَتُهِلَّ ‏","","",""],[1738,1738,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ السَّلَامِ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْرَمَ دُبُرَ الصَّلَاةِ ‏","","",""],[1739,1739,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏النَّضْرُ هُوَ ابْنُ شُمَيْلٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْرَمَ ‏ ‏أَوْ ‏ ‏أَهَلَّ ‏ ‏فِي دُبُرِ الصَّلَاةِ ‏","","",""],[1740,1740,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا لَبَّى قَالَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَذَكَرَ ‏ ‏نَافِعٌ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَزِيدُ هَؤُلَاءِ الْكَلِمَاتِ لَبَّيْكَ ‏ ‏وَالرَّغْبَاءُ إِلَيْكَ وَالْعَمَلُ لَبَّيْكَ لَبَّيْكَ ‏","","",""],[1741,1741,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَانِي ‏ ‏جِبْرَائِيلُ ‏ ‏فَقَالَ مُرْ أَصْحَابَكَ أَوْ مَنْ مَعَكَ أَنْ يَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ ‏ ‏أَوْ ‏ ‏بِالْإِهْلَالِ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏بِإِسْنَادِهِ ‏ ‏نَحْوَهُ ‏","","",""],[1742,1742,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏هِلَالُ بْنُ خَبَّابٍ ‏ ‏قَالَ فَحَدَّثْتُ ‏ ‏عِكْرِمَةَ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏ضُبَاعَةَ بِنْتَ الزُّبَيْرِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ أَنْ أَحُجَّ فَكَيْفَ أَقُولُ قَالَ قُولِي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ وَمَحِلِّي حَيْثُ تَحْبِسُنِي فَإِنَّ لَكِ عَلَى رَبِّكِ مَا اسْتَثْنَيْتِ ‏","","",""],[1743,1743,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْرَدَ الْحَجَّ ‏","","",""],[1744,1744,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ قَالَ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏إِنِّي مُحَدِّثُكَ بِحَدِيثٍ لَعَلَّ اللَّهَ أَنْ يَنْفَعَكَ بِهِ بَعْدُ ‏ ‏إِنَّهُ كَانَ يُسَلَّمُ عَلَيَّ وَإِنَّ ‏ ‏ابْنَ زِيَادٍ ‏ ‏أَمَرَنِي فَاكْتَوَيْتُ فَاحْتُبِسَ عَنِّي حَتَّى ذَهَبَ أَثَرُ الْمَكَاوِي وَاعْلَمْ أَنَّ ‏ ‏الْمُتْعَةَ ‏ ‏حَلَالٌ فِي كِتَابِ اللَّهِ لَمْ يَنْهَ عَنْهَا نَبِيٌّ وَلَمْ يَنْزِلْ فِيهَا كِتَابٌ قَالَ رَجُلٌ بِرَأْيِهِ مَا بَدَا لَهُ ‏","","",""],[1745,1745,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ نَوْفَلٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ عَامَ حَجَّ ‏ ‏مُعَاوِيَةُ ‏ ‏يَسْأَلُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏كَيْفَ تَقُولُ ‏ ‏بِالتَّمَتُّعِ ‏ ‏بِالْعُمْرَةِ إِلَى الْحَجِّ ‏ ‏قَالَ ‏ ‏حَسَنَةٌ جَمِيلَةٌ فَقَالَ قَدْ كَانَ ‏ ‏عُمَرُ ‏ ‏يَنْهَى عَنْهَا فَأَنْتَ خَيْرٌ مِنْ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏خَيْرٌ مِنِّي وَقَدْ فَعَلَ ذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ خَيْرٌ مِنْ ‏ ‏عُمَرَ ‏","","",""],[1746,1746,"","","‏ ‏حَدَّثَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَارِقٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ حَجَّ وَهُوَ ‏ ‏مُنِيخٌ ‏ ‏بِالْبَطْحَاءِ ‏ ‏فَقَالَ لِي ‏ ‏أَحَجَجْتَ قُلْتُ نَعَمْ قَالَ كَيْفَ ‏ ‏أَهْلَلْتَ ‏ ‏قَالَ قُلْتُ لَبَّيْكَ ‏ ‏بِإِهْلَالٍ ‏ ‏كَإِهْلَالِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحْسَنْتَ اذْهَبْ فَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ حِلَّ قَالَ فَطُفْتُ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ أَتَيْتُ امْرَأَةً مِنْ نِسَاءِ ‏ ‏بَنِي قَيْسٍ ‏ ‏فَجَعَلَتْ تَفْلِي رَأْسِي فَجَعَلْتُ أُفْتِي النَّاسَ بِذَلِكَ فَقَالَ لِي رَجُلٌ يَا ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏رُوَيْدًا بَعْضَ فُتْيَاكَ فَإِنَّكَ لَا تَدْرِي مَا أَحْدَثَ أَمِيرُ الْمُؤْمِنِينَ فِي ‏ ‏النُّسُكِ ‏ ‏بَعْدَكَ فَقُلْتُ يَا أَيُّهَا النَّاسُ مَنْ كُنَّا أَفْتَيْنَاهُ فُتْيَا ‏ ‏فَلْيَتَّئِدْ ‏ ‏فَإِنَّ ‏ ‏أَمِيرَ الْمُؤْمِنِينَ ‏ ‏قَادِمٌ عَلَيْكُمْ فَبِهِ فَأْتَمُّوا فَلَمَّا قَدِمَ أَتَيْتُهُ فَذَكَرْتُ ذَلِكَ لَهُ فَقَالَ إِنْ نَأْخُذْ بِكِتَابِ اللَّهِ فَإِنَّ كِتَابَ اللَّهِ يَأْمُرُ بِالتَّمَامِ وَإِنْ نَأْخُذْ بِسُنَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَحِلَّ حَتَّى بَلَغَ ‏ ‏الْهَدْيُ ‏ ‏مَحِلَّهُ ‏","","",""],[1747,1747,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خَمْسٌ لَا جُنَاحَ فِي قَتْلِ مَنْ قُتِلَ مِنْهُنَّ الْغُرَابُ وَالْفَأْرَةُ وَالْحِدَأَةُ وَالْعَقْرَبُ وَالْكَلْبُ الْعَقُورُ ‏","","",""],[1748,1748,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ خَمْسِ فَوَاسِقَ فِي الْحِلِّ وَالْحَرَمِ الْحِدَأَةِ وَالْغُرَابِ وَالْفَأْرَةِ وَالْعَقْرَبِ وَالْكَلْبِ الْعَقُورِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏الْكَلْبُ الْعَقُورُ وَقَالَ بَعْضُهُمْ الْأَسْوَدُ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏بَعْضُ أَصْحَابِنَا ‏ ‏إِنَّ ‏ ‏مَعْمَرًا ‏ ‏كَانَ يَذْكُرُهُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1749,1749,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[1750,1750,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلْقَمَةُ بْنُ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ابْنِ بُحَيْنَةَ ‏ ‏قَالَ ‏ ‏احْتَجَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَحْيِ جَمَلٍ وَهُوَ مُحْرِمٌ ‏","","",""],[1751,1751,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَطَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً عَنْ ‏ ‏عَطَاءٍ ‏ ‏وَمَرَّةً عَنْ ‏ ‏طَاوُسٍ ‏ ‏وَجَمَعَهُمَا مَرَّةً ‏","","",""],[1752,1752,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[1753,1753,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏نُبَيْهِ بْنِ وَهْبٍ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏قُرَيْشٍ ‏ ‏خَطَبَ إِلَى ‏ ‏أَبَانَ بْنِ عُثْمَانَ ‏ ‏وَهُوَ أَمِيرُ الْمَوْسِمِ ‏ ‏فَقَالَ ‏ ‏أَبَانُ ‏ ‏لَا أُرَاهُ عِرَاقِيًّا ‏ ‏جَافِيًا ‏ ‏إِنَّ الْمُحْرِمَ لَا يَنْكِحُ وَلَا يُنْكِحُ أَخْبَرَنَا بِذَلِكَ ‏ ‏عُثْمَانُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ ‏ ‏أَبُو مُحَمَّد ‏ ‏تَقُولُ بِهَذَا قَالَ ‏ ‏نَعَمْ ‏","","",""],[1754,1754,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ مِهْرَانَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَصَمِّ ‏ ‏أَنَّ ‏ ‏مَيْمُونَةَ ‏ ‏قَالَتْ ‏ ‏تَزَوَّجَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ حَلَالَانِ بَعْدَمَا رَجَعَ مِنْ ‏ ‏مَكَّةَ ‏ ‏بِسَرِفَ ‏","","",""],[1755,1755,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مَطَرٍ الْوَرَّاقِ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَيْمُونَةَ ‏ ‏حَلَالًا وَبَنَى بِهَا حَلَالًا وَكُنْتُ الرَّسُولَ بَيْنَهُمَا ‏","","",""],[1756,1756,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏قَالَ ‏ ‏انْطَلَقَ أَبِي مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏فَأَحْرَمَ أَصْحَابُهُ وَلَمْ يُحْرِمْ ‏ ‏أَبُو قَتَادَةَ ‏ ‏فَأَصَابَ حِمَارَ وَحْشٍ فَطَعَنَهُ وَأَكَلَ مِنْ لَحْمِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حِمَارَ وَحْشٍ فَطَعَنْتُهُ فَقَالَ لِلْقَوْمِ ‏ ‏كُلُوا وَهُمْ مُحْرِمُونَ ‏","","",""],[1757,1757,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ نَسِيرُ وَهُمْ مُحْرِمُونَ ‏ ‏وَأَبُو قَتَادَةَ ‏ ‏حَلَالٌ إِذْ رَأَيْتُ حِمَارًا فَرَكِبْتُ فَرَسًا فَأَصَبْتُهُ فَأَكَلُوا مِنْ لَحْمِهِ وَهُمْ مُحْرِمُونَ وَلَمْ آكُلْ فَأَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلُوهُ فَقَالَ ‏ ‏أَشَرْتُمْ قَتَلْتُمْ ‏ ‏أَوْ قَالَ ضَرَبْتُمْ ‏ ‏قَالُوا لَا قَالَ فَكُلُوا ‏","","",""],[1758,1758,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الصَّعْبِ بْنِ جَثَّامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِلَحْمِ حِمَارِ وَحْشٍ فَرَدَّهُ وَقَالَ ‏ ‏إِنَّا حُرُمٌ لَا نَأْكُلُ الصَّيْدَ ‏","","",""],[1759,1759,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عُثْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏فِي سَفَرٍ فَأُهْدِيَ لَهُ طَيْرٌ وَهُمْ مُحْرِمُونَ وَهُوَ رَاقِدٌ فَمِنَّا مَنْ أَكَلَ وَمِنَّا مَنْ تَوَرَّعَ فَاسْتَيْقَظَ ‏ ‏طَلْحَةُ ‏ ‏فَأَخْبَرُوهُ فَوَفَّقَ مَنْ أَكَلَهُ وَقَالَ ‏ ‏أَكَلْنَاهُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[1760,1760,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏الصَّعْبُ بْنُ جَثَّامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ بِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏بِالْأَبْوَاءِ ‏ ‏أَوْ ‏ ‏بِوَدَّانَ ‏ ‏فَأَهْدَيْتُ لَهُ لَحْمَ حِمَارِ وَحْشٍ فَرَدَّهُ عَلَيَّ فَلَمَّا رَأَى فِي وَجْهِي الْكَرَاهِيَةَ قَالَ ‏ ‏إِنَّهُ لَيْسَ بِنَا رَدٌّ عَلَيْكَ وَلَكِنَّا حُرُمٌ ‏","","",""],[1761,1761,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الرَّقَاشِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الْفَضْلِ بْنِ عَبَّاسٍ ‏ ‏أَنَّهُ كَانَ رَدِيفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ جَاءَتْ امْرَأَةٌ مِنْ ‏ ‏خَثْعَمَ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ فَرِيضَةَ اللَّهِ فِي الْحَجِّ عَلَى عِبَادِهِ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا لَا يَسْتَمْسِكُ عَلَى رَاحِلَتِهِ وَلَمْ يَحُجَّ أَفَأَحُجُّ عَنْهُ قَالَ نَعَمْ ‏ ‏سُئِلَ ‏ ‏أَبُو مُحَمَّد ‏ ‏تَقُولُ بِهَذَا ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1762,1762,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏الْفَضْلِ هُوَ ابْنُ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ أَبِي شَيْخٌ لَا يَسْتَوِي عَلَى الْبَعِيرِ أَدْرَكَتْهُ فَرِيضَةُ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُجِّي عَنْهُ ‏","","",""],[1763,1763,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ امْرَأَةً مِنْ ‏ ‏خَثْعَمَ ‏ ‏اسْتَفْتَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏وَالْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏رَدِيفُ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ فَرِيضَةَ اللَّهِ عَلَى عِبَادِهِ أَدْرَكَتْ أَبِي شَيْخًا كَبِيرًا لَا يَسْتَطِيعُ أَنْ يَسْتَوِيَ عَلَى الرَّاحِلَةِ فَهَلْ يَقْضِي أَنْ أَحُجَّ عَنْهُ قَالَ نَعَمْ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوًا مِنْ حَدِيثِ ‏ ‏الْأَوْزَاعِيِّ ‏","","",""],[1764,1764,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَقَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ يَسَارٍ ‏ ‏حَدَّثَنِي ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏أَوْ ‏ ‏عُبَيْدُ اللَّهِ بْنُ الْعَبَّاسِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ إِنَّ أَبِي ‏ ‏أَوْ أُمِّي ‏ ‏عَجُوزٌ كَبِيرٌ إِنْ أَنَا حَمَلْتُهَا لَمْ تَسْتَمْسِكْ وَإِنْ رَبَطْتُهَا خَشِيتُ أَنْ أَقْتُلَهَا قَالَ ‏ ‏أَرَأَيْتَ إِنْ كَانَ عَلَى أَبِيكَ ‏ ‏أَوْ أُمِّكَ ‏ ‏دَيْنٌ أَكُنْتَ ‏ ‏تَقْضِيهِ قَالَ نَعَمْ قَالَ فَحُجَّ عَنْ أَبِيكَ ‏ ‏أَوْ أُمِّكَ ‏ ‏قِيلَ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏الْحَجُّ عَنْ الْحَيِّ ‏ ‏قَالَ ‏ ‏إِذَا لَزِمَهُ ‏ ‏قِيلَ لَهُ تَقُولُ بِحَدِيثِ ‏ ‏الْفَضْلِ بْنِ الْعَبَّاسِ ‏ ‏قَالَ ‏ ‏نَعَمْ ‏","","",""],[1765,1765,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حُمَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ الزُّبَيْرِ ‏ ‏مَوْلًى لِآلِ ‏ ‏الْزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏خَثْعَمَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَبِي أَدْرَكَهُ الْإِسْلَامُ وَهُوَ شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ رُكُوبَ ‏ ‏الرَّحْلِ ‏ ‏وَالْحَجُّ مَكْتُوبٌ عَلَيْهِ أَفَأَحُجُّ عَنْهُ قَالَ ‏ ‏أَنْتَ أَكْبَرُ وَلَدِهِ قَالَ نَعَمْ قَالَ أَرَأَيْتَ لَوْ كَانَ عَلَى أَبِيكَ دَيْنٌ فَقَضَيْتَهُ عَنْهُ أَكَانَ ذَلِكَ يُجْزِئُ عَنْهُ قَالَ نَعَمْ قَالَ فَاحْجُجْ عَنْهُ ‏","","",""],[1766,1766,"","","‏ ‏أَخْبَرَنَا ‏ ‏صَالِحُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ هُوَ ابْنُ عَبْدِ الصَّمَدِ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏مَوْلَى ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏يُقَالُ لَهُ ‏ ‏يُوسُفُ بْنُ الزُّبَيْرِ ‏ ‏أَوْ ‏ ‏الزُّبَيْرُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سَوْدَةَ بِنْتِ زَمْعَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَبِي شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ أَنْ يَحُجَّ قَالَ ‏ ‏أَرَأَيْتَ لَوْ كَانَ عَلَى أَبِيكَ دَيْنٌ فَقَضَيْتَهُ عَنْهُ قُبِلَ مِنْهُ قَالَ نَعَمْ قَالَ اللَّهُ أَرْحَمُ حُجَّ عَنْ أَبِيكَ ‏","","",""],[1767,1767,"","","‏ ‏حَدَّثَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏مَا تَرَكْتُ اسْتِلَامَ هَذَيْنِ الرُّكْنَيْنِ فِي شِدَّةٍ وَلَا رَخَاءٍ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُهُمَا ‏ ‏قُلْتُ ‏ ‏لِنَافِعٍ ‏ ‏أَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَمْشِي بَيْنَ الرُّكْنَيْنِ قَالَ ‏ ‏إِنَّمَا كَانَ يَمْشِي لِيَكُونَ أَيْسَرَ لِاسْتِلَامِهِ ‏","","",""],[1768,1768,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏وَسُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُثْمَانَ بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَبْعَثَنَّ اللَّهُ الْحَجَرَ يَوْمَ الْقِيَامَةِ وَلَهُ عَيْنَانِ يُبْصِرُ بِهِمَا وَلِسَانٌ يَنْطِقُ بِهِ يَشْهَدُ عَلَى مَنْ اسْتَلَمَهُ بِحَقٍّ ‏ ‏قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏لِمَنْ اسْتَلَمَهُ ‏","","",""],[1769,1769,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْحَجَرِ إِلَى الْحَجَرِ ثَلَاثَةَ أَشْوَاطٍ ‏","","",""],[1770,1770,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏الطَّوَافَ الْأَوَّلَ ‏ ‏خَبَّ ‏ ‏ثَلَاثَةً وَمَشَى أَرْبَعَةً وَكَانَ ‏ ‏يَسْعَى ‏ ‏بِبَطْنِ الْمَسِيلِ ‏ ‏إِذَا سَعَى بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقُلْتُ ‏ ‏لِنَافِعٍ ‏ ‏أَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يَمْشِي إِذَا بَلَغَ الرُّكْنَ ‏ ‏الْيَمَانِيَ قَالَ ‏ ‏لَا إِلَّا أَنْ يُزَاحَمَ عَلَى الرُّكْنِ فَإِنَّهُ كَانَ لَا يَدَعُهُ حَتَّى يَسْتَلِمَهُ ‏","","",""],[1771,1771,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ بْنِ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَمَلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْحَجَرِ إِلَى الْحَجَرِ ثَلَاثًا وَمَشَى أَرْبَعًا ‏","","",""],[1772,1772,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ هُوَ ابْنُ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ يَعْلَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏طَافَ ‏ ‏مُضْطَبِعًا ‏","","",""],[1773,1773,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ وَالْعُمْرَةِ كَفَاهُ لَهُمَا طَوَافٌ وَاحِدٌ وَلَا يَحِلُّ حَتَّى يَحِلَّ مِنْهُمَا ‏","","",""],[1774,1774,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَافَ ‏ ‏بِالْبَيْتِ ‏ ‏عَلَى بَعِيرٍ كُلَّمَا أَتَى عَلَى الرُّكْنِ أَشَارَ إِلَيْهِ بِشَيْءٍ فِي يَدِهِ وَكَبَّرَ ‏","","",""],[1775,1775,"","","‏ ‏أَخْبَرَنَا ‏ ‏خَالِدُ بْنُ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏قَالَتْ ‏ ‏قَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏وَأَنَا حَائِضٌ وَلَمْ أَطُفْ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏افْعَلِي مَا يَفْعَلُ الْحَاجُّ غَيْرَ أَنْ لَا تَطُوفِي ‏ ‏بِالْبَيْتِ ‏","","",""],[1776,1776,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْحُمَيْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْفُضَيْلُ بْنُ عِيَاضٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطَّوَافُ ‏ ‏بِالْبَيْتِ ‏ ‏صَلَاةٌ إِلَّا أَنَّ اللَّهَ أَحَلَّ فِيهِ الْمَنْطِقَ فَمَنْ نَطَقَ فِيهِ فَلَا يَنْطِقْ إِلَّا بِخَيْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ مَعْبَدٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ أَعْيَنَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[1777,1777,"","","‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَافَقْتُ رَبِّي فِي ثَلَاثٍ قُلْتُ يَا رَسُولَ اللَّهِ لَوْ اتَّخَذْتَ مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏وَاتَّخِذُوا مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى ‏}","","",""],[1778,1778,"","","‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَعِيلُ بْنُ أَبَانَ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو جَعْفَرٍ ‏ ‏دَخَلْنَا عَلَى ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏فَسَأَلَ عَنْ الْقَوْمِ حَتَّى انْتَهَى إِلَيَّ فَقُلْتُ أَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيِّ بْنِ الْحُسَيْنِ بْنِ عَلِيٍّ ‏ ‏فَأَهْوَى بِيَدِهِ إِلَى ‏ ‏زِرِّيَ الْأَعْلَى ‏ ‏وَزِرِّيَ الْأَسْفَلِ ثُمَّ وَضَعَ فَمَهُ بَيْنَ ثَدْيَيَّ وَأَنَا يَوْمَئِذٍ غُلَامٌ شَابٌّ فَقَالَ مَرْحَبًا بِكَ يَا ابْنَ أَخِي سَلْ عَمَّا شِئْتَ فَسَأَلْتُهُ وَهُوَ أَعْمَى وَجَاءَ وَقْتُ الصَّلَاةِ فَقَامَ فِي ‏ ‏سَاجَةٍ ‏ ‏مُلْتَحِفًا بِهَا كُلَّمَا وَضَعَهَا عَلَى مَنْكِبَيْهِ رَجَعَ طَرَفُهَا إِلَيْهِ مِنْ صِغَرِهَا وَرِدَاؤُهُ إِلَى جَنْبِهِ عَلَى ‏ ‏الْمِشْجَبِ ‏ ‏فَصَلَّى فَقُلْتُ أَخْبِرْنِي عَنْ حَجَّةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بِيَدِهِ فَعَقَدَ تِسْعًا فَقَالَ مَكَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تِسْعَ سِنِينَ لَمْ يَحُجَّ ثُمَّ أُذِّنَ فِي النَّاسِ بِالْحَجِّ فِي الْعَاشِرَةِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجٌّ فَقَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏بَشَرٌ كَثِيرٌ كُلُّهُمْ يَلْتَمِسُ أَنْ يَأْتَمَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَعْمَلَ مِثْلَ عَمَلِهِ فَخَرَجْنَا مَعَهُ حَتَّى أَتَيْنَا ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏فَوَلَدَتْ ‏ ‏أَسْمَاءُ بِنْتُ عُمَيْسٍ ‏ ‏مُحَمَّدَ بْنَ أَبِي بَكْرٍ ‏ ‏فَأَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ أَصْنَعُ فَقَالَ اغْتَسِلِي ‏ ‏وَاسْتَثْفِرِي ‏ ‏بِثَوْبٍ وَأَحْرِمِي فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ ثُمَّ رَكِبَ الْقَصْوَاءَ حَتَّى اسْتَوَتْ بِهِ نَاقَتُهُ عَلَى ‏ ‏الْبَيْدَاءِ ‏ ‏فَنَظَرْتُ إِلَى مَدِّ بَصَرِي مِنْ بَيْنِ يَدَيْهِ مِنْ رَاكِبٍ وَمَاشٍ وَعَنْ يَمِينِهِ مِثْلُ ذَلِكَ وَعَنْ يَسَارِهِ مِثْلُ ذَلِكَ وَخَلْفَهُ مِثْلُ ذَلِكَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَظْهُرِنَا وَعَلَيْهِ يُنْزَلُ الْقُرْآنُ وَهُوَ يَعْرِفُ ‏ ‏تَأْوِيلَهُ ‏ ‏فَأَهَلَّ ‏ ‏بِالتَّوْحِيدِ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏فَأَهَلَّ ‏ ‏النَّاسُ بِهَذَا الَّذِي ‏ ‏يُهِلُّونَ ‏ ‏بِهِ فَلَمْ يَزِدْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْهِمْ شَيْئًا وَلَبَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَلْبِيَتَهُ حَتَّى إِذَا أَتَيْنَا ‏ ‏الْبَيْتَ ‏ ‏مَعَهُ ‏ ‏قَالَ ‏ ‏جَابِرٌ ‏ ‏لَسْنَا ‏ ‏نَنْوِي إِلَّا الْحَجَّ لَسْنَا نَعْرِفُ الْعُمْرَةَ ‏ ‏حَتَّى إِذَا أَتَيْنَا ‏ ‏الْبَيْتَ ‏ ‏مَعَهُ اسْتَلَمَ الرُّكْنَ ‏ ‏فَرَمَلَ ‏ ‏ثَلَاثًا وَمَشَى أَرْبَعًا ثُمَّ تَقَدَّمَ إِلَى ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَصَلَّى فَقَرَأَ ‏ { ‏وَاتَّخِذُوا مِنْ ‏ ‏مَقَامِ ‏ ‏إِبْرَاهِيمَ ‏ ‏مُصَلًّى ‏} ‏فَجَعَلَ ‏ ‏الْمَقَامَ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏وَكَانَ أَبِي يَقُولُ وَلَا أَعْلَمُهُ ذَكَرَهُ عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ يَقْرَأُ فِي الرَّكْعَتَيْنِ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏ثُمَّ رَجَعَ إِلَى الرُّكْنِ فَاسْتَلَمَهُ ثُمَّ خَرَجَ مِنْ الْبَابِ إِلَى ‏ ‏الصَّفَا ‏ ‏فَلَمَّا أَتَى ‏ ‏الصَّفَا ‏ ‏قَرَأَ ‏ { ‏إِنَّ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةَ ‏ ‏مِنْ شَعَائِرِ اللَّهِ ‏} ‏أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ فَبَدَأَ ‏ ‏بِالصَّفَا ‏ ‏فَرَقِيَ عَلَيْهِ حَتَّى رَأَى ‏ ‏الْبَيْتَ ‏ ‏فَوَحَّدَ اللَّهَ وَكَبَّرَهُ وَقَالَ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ثُمَّ دَعَا بَيْنَ ذَلِكَ فَقَالَ مِثْلَ هَذَا ثَلَاثَ مَرَّاتٍ ثُمَّ نَزَلَ إِلَى ‏ ‏الْمَرْوَةِ ‏ ‏حَتَّى إِذَا انْصَبَّتْ قَدَمَاهُ فِي بَطْنِ الْوَادِي ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ الرَّحْمَنِ الدَّارِمِيُّ ‏ ‏يَعْنِي ‏ ‏فَرَمَلَ ‏ ‏حَتَّى إِذَا صَعِدْنَا مَشَى حَتَّى إِذَا أَتَيْنَا ‏ ‏الْمَرْوَةَ ‏ ‏فَفَعَلَ عَلَى ‏ ‏الْمَرْوَةِ ‏ ‏كَمَا فَعَلَ عَلَى ‏ ‏الصَّفَا ‏ ‏حَتَّى إِذَا كَانَ آخِرَ طَوَافٍ عَلَى ‏ ‏الْمَرْوَةِ ‏ ‏قَالَ إِنِّي لَوْ اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ لَمْ أَسُقْ ‏ ‏الْهَدْيَ ‏ ‏وَجَعَلْتُهَا عُمْرَةً فَمَنْ كَانَ مِنْكُمْ لَيْسَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيُحِلَّ وَيَجْعَلْهَا عُمْرَةً فَقَامَ ‏ ‏سُرَاقَةُ بْنُ مَالِكِ بْنِ جُعْشُمٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَلِعَامِنَا هَذَا أَوْ لِأَبَدِ أَبَدٍ فَشَبَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصَابِعَهُ فِي الْأُخْرَى فَقَالَ دَخَلَتْ الْعُمْرَةُ فِي الْحَجِّ هَكَذَا مَرَّتَيْنِ لَا بَلْ لِأَبَدِ أَبَدٍ لَا بَلْ لَأَبَدِ أَبَدٍ وَقَدِمَ ‏ ‏عَلِيٌّ ‏ ‏بِبُدْنٍ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدَ ‏ ‏فَاطِمَةَ ‏ ‏مِمَّنْ حَلَّ وَلَبِسَتْ ثِيَابَ صَبِيغٍ وَاكْتَحَلَتْ فَأَنْكَرَ ‏ ‏عَلِيٌّ ‏ ‏ذَلِكَ عَلَيْهَا فَقَالَتْ أَبِي أَمَرَنِي فَكَانَ ‏ ‏عَلِيٌّ ‏ ‏يَقُولُ ذَهَبْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُحَرِّشُهُ ‏ ‏عَلَى ‏ ‏فَاطِمَةَ ‏ ‏فِي الَّذِي صَنَعَتْ مُسْتَفْتِيًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا ذَكَرَتْ فَأَنْكَرْتُ ذَلِكَ عَلَيْهَا فَقَالَ صَدَقَتْ مَا فَعَلْتَ حِينَ فَرَضْتَ الْحَجَّ قَالَ قُلْتُ اللَّهُمَّ إِنِّي ‏ ‏أُهِلُّ ‏ ‏بِمَا ‏ ‏أَهَلَّ ‏ ‏بِهِ رَسُولُكَ قَالَ فَإِنَّ ‏ ‏مَعِيَ ‏ ‏الْهَدْيَ ‏ ‏فَلَا تَحْلِلْ قَالَ فَكَانَ جَمَاعَةُ ‏ ‏الْهَدْيِ ‏ ‏الَّذِي قَدِمَ بِهِ ‏ ‏عَلِيٌّ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏وَالَّذِي أَتَى بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِائَةَ ‏ ‏بَدَنَةٍ ‏ ‏فَحَلَّ النَّاسُ كُلُّهُمْ وَقَصَّرُوا إِلَّا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلَمَّا كَانَ ‏ ‏يَوْمُ التَّرْوِيَةِ ‏ ‏وَجَّهَ إِلَى ‏ ‏مِنًى ‏ ‏فَأَهْلَلْنَا ‏ ‏بِالْحَجِّ وَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى بِنَا الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ وَالصُّبْحَ ثُمَّ مَكَثَ قَلِيلًا حَتَّى إِذَا طَلَعَتْ الشَّمْسُ أَمَرَ ‏ ‏بِقُبَّةٍ ‏ ‏مِنْ شَعَرٍ تُضْرَبُ لَهُ ‏ ‏بِنَمِرَةَ ‏ ‏ثُمَّ رَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَارَ لَا تَشُكُّ ‏ ‏قُرَيْشٌ ‏ ‏إِلَّا أَنَّهُ وَاقِفٌ عِنْدَ ‏ ‏الْمَشْعَرِ الْحَرَامِ ‏ ‏كَمَا كَانَتْ ‏ ‏قُرَيْشٌ ‏ ‏تَصْنَعُ فِي الْجَاهِلِيَّةِ فِي ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فَسَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَتَى ‏ ‏عَرَفَةَ ‏ ‏فَوَجَدَ الْقُبَّةَ قَدْ ضُرِبَتْ ‏ ‏بِنَمِرَةَ ‏ ‏فَنَزَلَهَا حَتَّى إِذَا زَاغَتْ ‏ ‏يَعْنِي الشَّمْسَ ‏ ‏أَمَرَ بِالْقَصْوَاءِ فَرُحِّلَتْ لَهُ فَأَتَى بَطْنَ الْوَادِي فَخَطَبَ النَّاسَ وَقَالَ إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلَا إِنَّ كُلَّ شَيْءٍ مِنْ أَمْرِ الْجَاهِلِيَّةِ تَحْتَ قَدَمَيَّ مَوْضُوعٌ وَدِمَاءُ الْجَاهِلِيَّةِ مَوْضُوعَةٌ وَأَوَّلُ دَمٍ وُضِعَ دِمَاؤُنَا دَمُ ‏ ‏رَبِيعَةَ بْنِ الْحَارِثِ ‏ ‏كَانَ مُسْتَرْضَعًا فِي ‏ ‏بَنِي سَعْدٍ ‏ ‏فَقَتَلَتْهُ ‏ ‏هُذَيْلٌ ‏ ‏وَرِبَا الْجَاهِلِيَّةِ مَوْضُوعٌ وَأَوَّلُ رِبًا أَضَعُهُ رِبَا ‏ ‏عَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏فَإِنَّهُ مَوْضُوعٌ كُلُّهُ فَاتَّقُوا اللَّهَ فِي النِّسَاءِ فَإِنَّمَا أَخَذْتُمُوهُنَّ بِأَمَانَةِ اللَّهِ وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ وَإِنَّ لَكُمْ عَلَيْهِنَّ أَنْ لَا يُوطِئْنَ فُرُشَكُمْ أَحَدًا تَكْرَهُونَهُ فَإِنْ فَعَلْنَ ذَلِكَ فَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ ‏ ‏مُبَرِّحٍ ‏ ‏وَلَهُنَّ عَلَيْكُمْ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ وَأَنْتُمْ مَسْئُولُونَ عَنِّي فَمَا أَنْتُمْ قَائِلُونَ قَالُوا نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ وَأَدَّيْتَ وَنَصَحْتَ فَقَالَ بِأُصْبُعِهِ السَّبَّابَةِ فَرَفَعَهَا إِلَى السَّمَاءِ ‏ ‏وَيَنْكُتُهَا ‏ ‏إِلَى النَّاسِ اللَّهُمَّ اشْهَدْ اللَّهُمَّ اشْهَدْ اللَّهُمَّ اشْهَدْ ثُمَّ أَذَّنَ ‏ ‏بِلَالٌ ‏ ‏بِنِدَاءٍ وَاحِدٍ وَإِقَامَةٍ فَصَلَّى الظُّهْرَ ثُمَّ أَقَامَ فَصَلَّى الْعَصْرَ لَمْ يُصَلِّ بَيْنَهُمَا شَيْئًا ثُمَّ رَكِبَ حَتَّى وَقَفَ فَجَعَلَ بَطْنَ نَاقَتِهِ الْقَصْوَاءِ إِلَى ‏ ‏الصُّخَيْرَاتِ ‏ ‏وَقَالَ ‏ ‏إِسْمَعِيلُ ‏ ‏إِلَى الشُّجَيْرَاتِ ‏ ‏وَجَعَلَ حَبْلَ الْمُشَاةِ بَيْنَ يَدَيْهِ ثُمَّ اسْتَقْبَلَ الْقِبْلَةَ فَلَمْ يَزَلْ وَاقِفًا حَتَّى غَرَبَتْ الشَّمْسُ وَذَهَبَتْ الصُّفْرَةُ حَتَّى غَابَ الْقُرْصُ فَأَرْدَفَ ‏ ‏أُسَامَةَ ‏ ‏خَلْفَهُ ثُمَّ دَفَعَ وَقَدْ ‏ ‏شَنَقَ ‏ ‏لِلْقَصْوَاءِ الزِّمَامَ حَتَّى إِنَّهُ لَيُصِيبُ رَأْسُهَا ‏ ‏مَوْرِكَ رَحْلِهِ ‏ ‏وَيَقُولُ بِيَدِهِ الْيُمْنَى السَّكِينَةَ السَّكِينَةَ كُلَّمَا أَتَى حَبْلًا مِنْ الْحِبَالِ أَرْخَى لَهَا قَلِيلًا حَتَّى تَصْعَدَ حَتَّى أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَصَلَّى بِهَا الْمَغْرِبَ وَالْعِشَاءَ بِأَذَانٍ وَإِقَامَتَيْنِ ثُمَّ اضْطَجَعَ حَتَّى إِذَا طَلَعَ الْفَجْرُ صَلَّى الْفَجْرَ بِأَذَانٍ وَإِقَامَةٍ ثُمَّ رَكِبَ الْقَصْوَاءَ حَتَّى وَقَفَ عَلَى ‏ ‏الْمَشْعَرِ الْحَرَامِ ‏ ‏وَاسْتَقْبَلَ الْقِبْلَةَ فَدَعَا اللَّهَ وَكَبَّرَهُ وَهَلَّلَهُ وَوَحَّدَهُ حَتَّى أَسْفَرَ جِدًّا ثُمَّ دَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ وَأَرْدَفَ ‏ ‏الْفَضْلَ بْنَ الْعَبَّاسِ ‏ ‏وَكَانَ رَجُلًا حَسَنَ الشَّعْرِ أَبْيَضَ وَسِيمًا فَلَمَّا دَفَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِالظُّعُنِ ‏ ‏يَجْرِينَ ‏ ‏فَطَفِقَ ‏ ‏الْفَضْلُ ‏ ‏يَنْظُرُ إِلَيْهِنَّ فَأَخَذَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فَوَضَعَهَا عَلَى وَجْهِ ‏ ‏الْفَضْلِ ‏ ‏فَحَوَّلَ ‏ ‏الْفَضْلُ ‏ ‏رَأْسَهُ مِنْ الشِّقِّ الْآخَرِ فَوَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ مِنْ الشِّقِّ الْآخَرِ حَتَّى إِذَا أَتَى ‏ ‏مُحَسِّرَ ‏ ‏حَرَّكَ قَلِيلًا ثُمَّ سَلَكَ الطَّرِيقَ الْوُسْطَى الَّتِي تُخْرِجُكَ إِلَى ‏ ‏الْجَمْرَةِ الْكُبْرَى ‏ ‏حَتَّى إِذَا أَتَى ‏ ‏الْجَمْرَةَ ‏ ‏الَّتِي عِنْدَهَا الشَّجَرَةُ فَرَمَى بِسَبْعِ حَصَيَاتٍ يُكَبِّرُ عَلَى كُلِّ حَصَاةٍ مِنْ حَصَى ‏ ‏الْخَذْفِ ‏ ‏ثُمَّ رَمَى مِنْ بَطْنِ الْوَادِي ثُمَّ انْصَرَفَ إِلَى الْمَنْحَرِ فَنَحَرَ ثَلَاثًا وَسِتِّينَ بَدَنَةً بِيَدِهِ ثُمَّ أَعْطَى ‏ ‏عَلِيًّا ‏ ‏فَنَحَرَ مَا ‏ ‏غَبَرَ ‏ ‏وَأَشْرَكَهُ فِي ‏ ‏بُدْنِهِ ‏ ‏ثُمَّ أَمَرَ مِنْ كُلِّ ‏ ‏بَدَنَةٍ ‏ ‏بِبَضْعَةٍ ‏ ‏فَجُعِلَتْ فِي قِدْرٍ فَطُبِخَتْ فَأَكَلَا مِنْ لُحُومِهَا وَشَرِبَا مِنْ مَرَقِهَا ثُمَّ رَكِبَ ‏ ‏فَأَفَاضَ ‏ ‏إِلَى ‏ ‏الْبَيْتِ ‏ ‏فَأَتَى ‏ ‏الْبَيْتَ ‏ ‏فَصَلَّى الظُّهْرَ ‏ ‏بِمَكَّةَ ‏ ‏وَأَتَى ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏وَهُمْ يَسْتَقُونَ عَلَى ‏ ‏زَمْزَمَ ‏ ‏فَقَالَ انْزِعُوا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏فَلَوْلَا يَغْلِبُكُمْ النَّاسُ عَلَى سِقَايَتِكُمْ لَنَزَعْتُ مَعَكُمْ فَنَاوَلُوهُ دَلْوًا فَشَرِبَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ سَعِيدٍ الْأَصْبَهَانِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَعِيلَ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏بِهَذَا ‏","","",""],[1779,1779,"","","‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ هُوَ ابْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏بَيْنَا رَجُلٌ وَاقِفٌ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِعَرَفَةَ ‏ ‏فَوَقَعَ عَنْ رَاحِلَتِهِ ‏ ‏أَوْ قَالَ ‏ ‏فَأَقْعَصَتْهُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اغْسِلُوهُ بِمَاءٍ وَسِدْرٍ وَكَفِّنُوهُ فِي ثَوْبَيْنِ وَلَا ‏ ‏تُحَنِّطُوهُ ‏ ‏وَلَا ‏ ‏تُخَمِّرُوا ‏ ‏رَأْسَهُ فَإِنَّ اللَّهَ تَعَالَى يَبْعَثُهُ يَوْمَ الْقِيَامَةِ مُلَبِّيًا ‏","","",""],[1780,1780,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّمَا جُعِلَ الطَّوَافُ ‏ ‏بِالْبَيْتِ ‏ ‏وَرَمْيُ الْجِمَارِ وَالسَّعْيُ بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏لِإِقَامَةِ ذِكْرِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو عَاصِمٍ ‏ ‏كَانَ يَرْفَعُهُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏وَمُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[1781,1781,"","","‏ ‏أَخْبَرَنَا ‏ ‏نُعَيْمُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏فَسْخُ الْحَجِّ لَنَا خَاصَّةً أَمْ لِمَنْ بَعْدَنَا قَالَ بَلْ لَنَا خَاصَّةً ‏","","",""],[1782,1782,"","","‏ ‏أَخْبَرَنَا ‏ ‏سَهْلُ بْنُ حَمَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هَذِهِ عُمْرَةٌ ‏ ‏اسْتَمْتَعْنَا ‏ ‏بِهَا فَمَنْ لَمْ يَكُنْ مَعَهُ ‏ ‏هَدْيٌ ‏ ‏فَلْيَحِلَّ الْحِلَّ كُلَّهُ فَقَدْ دَخَلَتْ الْعُمْرَةُ فِي الْحَجِّ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[1783,1783,"","","‏ ‏أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏رَبِيعِ بْنِ سَبْرَةَ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُمْ سَارُوا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى بَلَغُوا ‏ ‏عُسْفَانَ ‏ ‏فَقَالَ لَهُ رَجُلٌ مِنْ ‏ ‏بَنِي مُدْلِجٍ ‏ ‏يُقَالُ لَهُ ‏ ‏مَالِكُ بْنُ سُرَاقَةَ ‏ ‏أَوْ ‏ ‏سُرَاقَةُ بْنُ مَالِكٍ ‏ ‏اقْضِ لَنَا قَضَاءَ قَوْمٍ وُلِدُوا الْيَوْمَ قَالَ ‏ ‏إِنَّ اللَّهَ قَدْ أَدْخَلَ عَلَيْكُمْ فِي حَجِّكُمْ هَذَا عُمْرَةً فَإِذَا أَنْتُمْ قَدِمْتُمْ فَمَنْ تَطَوَّفَ ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَقَدْ حَلَّ إِلَّا مَنْ كَانَ مَعَهُ ‏ ‏هَدْيٌ ‏","","",""],[1784,1784,"","","‏ ‏أَخْبَرَنَا ‏ ‏شِهَابُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اعْتَمَرَ أَرْبَعَ عُمَرٍ عُمْرَةَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَعُمْرَةَ الْقَضَاءِ ‏ ‏أَوْ قَالَ عُمْرَةَ الْقِصَاصِ شَكَّ ‏ ‏شِهَابُ بْنُ عَبَّادٍ ‏ ‏مِنْ قَابِلٍ وَالثَّالِثَةَ مِنْ ‏ ‏الْجِعْرَانَةِ ‏ ‏وَالرَّابِعَةَ الَّتِي مَعَ حَجَّتِهِ ‏","","",""],[1785,1785,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِامْرَأَةٍ ‏ ‏اعْتَمِرِي فِي رَمَضَانَ فَإِنَّ عُمْرَةً فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[1786,1786,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَقَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ مَعْقِلِ بْنِ أَبِي مَعْقَلٍ الْأَسَدِيِّ ‏ ‏أَسَدُ ‏ ‏خُزَيْمَةَ ‏ ‏حَدَّثَنِي ‏ ‏يُوسُفُ بْنُ عَبْدِ اللَّهِ بْنِ سَلَامٍ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ ‏ ‏أُمِّ مَعْقَلٍ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمْرَةٌ فِي رَمَضَانَ تَعْدِلُ حَجَّةً ‏","","",""],[1787,1787,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْبَزَّازُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُزَاحِمُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَرِّشٍ الْكَعْبِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ مِنْ ‏ ‏الْجِعْرَانَةِ ‏ ‏حِينَ أَنْشَأَ مُعْتَمِرًا فَدَخَلَ ‏ ‏مَكَّةَ ‏ ‏لَيْلًا فَقَضَى عُمْرَتَهُ ثُمَّ خَرَجَ مِنْ تَحْتِ لَيْلَتِهِ فَأَصْبَحَ ‏ ‏بِالْجِعْرَانَةِ ‏ ‏كَبَائِتٍ ‏","","",""],[1788,1788,"","","‏ ‏حَدَّثَنَا ‏ ‏صَدَقَةُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏سَمِعَ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ ‏ ‏يَقُولُ ‏ ‏أَمَرَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ أُرْدِفَ ‏ ‏عَائِشَةَ ‏ ‏فَأُعْمِرَهَا مِنْ ‏ ‏التَّنْعِيمِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَانَ ‏ ‏شُعْبَةُ ‏ ‏يُعْجِبُهُ مِثْلَ هَذَا الْإِسْنَادِ ‏","","",""],[1789,1789,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏ابْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏عَنْ ‏ ‏أَبِيهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ ‏ ‏أَرْدِفْ أُخْتَكَ ‏ ‏يَعْنِي ‏ ‏عَائِشَةَ ‏ ‏وَأَعْمِرْهَا مِنْ ‏ ‏التَّنْعِيمِ ‏ ‏فَإِذَا هَبَطْتَ مِنْ ‏ ‏الْأَكَمَةِ ‏ ‏فَمُرْهَا فَلْتُحْرِمْ فَإِنَّهَا عُمْرَةٌ مُتَقَبَّلَةٌ ‏","","",""],[1790,1790,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُسَدَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأُقَبِّلُكَ وَإِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ وَلَكِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُكَ ‏","","",""],[1791,1791,"","","‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏قَالَ رَأَيْتُ ‏ ‏مُحَمَّدَ بْنَ عَبَّادِ بْنِ جَعْفَرٍ ‏ ‏يَسْتَلِمُ الْحَجَرَ ثُمَّ يُقَبِّلُهُ وَيَسْجُدُ عَلَيْهِ فَقُلْتُ لَهُ مَا هَذَا ‏ ‏فَقَالَ ‏ ‏رَأَيْتُ خَالَكَ ‏ ‏عَبْدَ اللَّهِ بْنَ عَبَّاسٍ ‏ ‏يَفْعَلُهُ ثُمَّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عُمَرَ ‏ ‏فَعَلَهُ ثُمَّ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَعْلَمُ أَنَّكَ حَجَرٌ وَلَكِنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ هَذَا ‏","","",""],[1792,1792,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مِنْهَالٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏وَرَدِيفُهُ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَأَنَاخَ ‏ ‏فِي أَصْلِ ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَسَعَى النَّاسُ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِلَالٌ ‏ ‏وَأُسَامَةُ ‏ ‏فَقُلْتُ ‏ ‏لِبِلَالٍ ‏ ‏مِنْ وَرَاءِ الْبَابِ أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَيْنَ ‏ ‏السَّارِيَتَيْنِ ‏ ‏أَخْبَرَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ اللَّهِ بْنِ يُونُسَ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏هُوَ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَبِلَالٌ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ الْحَجَبِيُّ ‏ ‏فَذَكَرَ ‏ ‏نَحْوَهُ ‏","","",""],[1793,1793,"","","‏ ‏حَدَّثَنِي ‏ ‏فَرْوَةُ بْنُ أَبِي الْمَغْرَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا حَدَاثَةُ عَهْدِ قَوْمِكِ بِالْكُفْرِ لَنَقَضْتُ ‏ ‏الْكَعْبَةَ ‏ ‏ثُمَّ لَبَنَيْتُهَا عَلَى ‏ ‏أُسِّ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَإِنَّ ‏ ‏قُرَيْشًا ‏ ‏حِينَ بَنَتْ ‏ ‏اسْتَقْصَرَتْ ‏ ‏ثُمَّ جَعَلَتْ لَهَا ‏ ‏خَلْفًا ‏","","",""],[1794,1794,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْجَدْرِ ‏ ‏أَمِنَ ‏ ‏الْبَيْتِ ‏ ‏هُوَ قَالَ ‏ ‏نَعَمْ قُلْتُ فَمَا لَهُمْ لَمْ يُدْخِلُوهُ فِي ‏ ‏الْبَيْتِ ‏ ‏فَقَالَ إِنَّ قَوْمَكِ قَصَّرَتْ بِهِمْ النَّفَقَةُ قُلْتُ فَمَا شَأْنُ بَابِهِ مُرْتَفِعًا قَالَ فَعَلَ ذَلِكَ قَوْمُكِ لِيُدْخِلُوا مَنْ شَاءُوا وَيَمْنَعُوا مَنْ شَاءُوا وَلَوْلَا أَنَّ قَوْمَكِ حَدِيثُ عَهْدٍ بِجَاهِلِيَّةٍ فَأَخَافُ أَنْ تُنْكِرَ قُلُوبُهُمْ لَعَمَدْتُ إِلَى ‏ ‏الْحِجْرِ ‏ ‏فَجَعَلْتُهُ فِي ‏ ‏الْبَيْتِ ‏ ‏وَأَلْزَقْتُ بَابَهُ بِالْأَرْضِ ‏","","",""],[1795,1795,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏التَّحْصِيبُ ‏ ‏لَيْسَ بِشَيْءٍ إِنَّمَا هُوَ مَنْزِلٌ نَزَلَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو مُحَمَّد ‏ ‏التَّحْصِيبُ ‏ ‏مَوْضِعٌ ‏ ‏بِمَكَّةَ ‏ ‏وَهُوَ مَوْضِعٌ ‏ ‏بِبَطْحَاءَ ‏","","",""],[1796,1796,"","","‏ ‏أَخْبَرَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُدَيْنَةَ ‏ ‏هُوَ ‏ ‏يَحْيَى بْنُ الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏مِقْسَمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏خَمْسَ صَلَوَاتٍ ‏","","",""],[1797,1797,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ ‏ ‏وَأَحْمَدُ بْنُ مُحَمَّدِ بْنِ حَنْبَلٍ ‏ ‏عَنْ ‏ ‏إِسْحَقَ بْنِ يُوسُفَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ رُفَيْعٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِأَنَسِ بْنِ مَالِكٍ ‏ ‏حَدِّثْنِي بِشَيْءٍ عَقَلْتَهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ صَلَّى الظُّهْرَ ‏ ‏يَوْمَ التَّرْوِيَةِ ‏ ‏قَالَ ‏ ‏بِمِنًى ‏ ‏قَالَ قُلْتُ فَأَيْنَ صَلَّى الْعَصْرَ ‏ ‏يَوْمَ النَّفْرِ ‏ ‏قَالَ ‏ ‏بِالْأَبْطَحِ ‏ ‏ثُمَّ قَالَ اصْنَعْ مَا يَصْنَعُ أُمَرَاؤُكَ ‏","","",""],[1798,1798,"","","‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏اللَّيْثُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُ حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الظُّهْرَ وَالْعَصْرَ وَالْمَغْرِبَ وَالْعِشَاءَ وَرَقَدَ رَقْدَةً ‏ ‏بِمِنًى ‏ ‏ثُمَّ رَكِبَ إِلَى ‏ ‏الْبَيْتِ ‏ ‏فَطَافَ بِهِ ‏","","",""],[1799,1799,"","","‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ الصَّلْتِ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَصَلَّى مَعَ ‏ ‏عُثْمَانَ ‏ ‏بِمِنًى ‏ ‏أَرْبَعَ رَكَعَاتٍ لَقَدْ ‏ ‏صَلَّيْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ رَكْعَتَيْنِ رَكْعَتَيْنِ وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏رَكْعَتَيْنِ رَكْعَتَيْنِ وَمَعَ ‏ ‏عُمَرَ ‏ ‏رَكْعَتَيْنِ رَكْعَتَيْنِ ثُمَّ تَفَرَّقَتْ بِكُمْ الطُّرُقُ فَلَيْتَ حَظِّي مِنْ أَرْبَعِ رَكَعَاتٍ رَكْعَتَانِ مُتَقَبَّلَتَانِ ‏","","",""],[1800,1800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏رَكْعَتَيْنِ ‏ ‏وَعُمَرَ ‏ ‏رَكْعَتَيْنِ ‏ ‏وَعُثْمَانَ ‏ ‏رَكْعَتَيْنِ صَدْرًا مِنْ إِمَارَتِهِ ثُمَّ أَتَمَّهَا بَعْدُ ‏","","",""]];
